INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accommodation-1', 'accommodation', 'The university offers cheap accommodation to all first-year students.', '这所大学为所有大一新生提供便宜的住宿。', 'accommodation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('landlord-1', 'landlord', 'The landlord has agreed to replace the broken cooker by next Monday.', '房东已经同意在下周一前换掉坏了的灶具。', 'landlord');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('landlady-1', 'landlady', 'My landlady lives downstairs and doesn''t allow pets in the house.', '我的女房东住在楼下,她不允许在房子里养宠物。', 'landlady');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tenant-1', 'tenant', 'The tenant must report any repairs to the landlord within two days.', '租户必须在两天内向房东报修。', 'tenant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lease-1', 'lease', 'We signed a one-year lease, so we can''t move out before June.', '我们签了一年的租约,所以六月之前不能搬走。', 'lease');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lease-2', 'lease', 'The company leases three flats near the station to its new staff.', '公司把车站附近的三套公寓租给新员工。', 'leases');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tenancy-1', 'tenancy', 'The tenancy runs for twelve months and starts on the first of September.', '租期为十二个月,从九月一日开始。', 'tenancy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rent-1', 'rent', 'The rent is due on the first day of every month.', '租金在每月第一天到期。', 'rent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rent-2', 'rent', 'We decided to rent a small house close to the beach.', '我们决定在海滩附近租一栋小房子。', 'rent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('security-deposit-1', 'security-deposit', 'You''ll get your security deposit back when you move out of the flat.', '你搬出公寓时,押金会退还给你。', 'security deposit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('utilities-1', 'utilities', 'Does the monthly rent include utilities such as gas and electricity?', '月租包含煤气、电费这类费用吗?', 'utilities');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bill-1', 'bill', 'Could you pay the electricity bill before you go on holiday?', '你去度假前能把电费账单付了吗?', 'bill');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inclusive-1', 'inclusive', 'The rent is £150 a week, inclusive of gas and water.', '租金每周 150 英镑,包含煤气费和水费。', 'inclusive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('furnished-1', 'furnished', 'The flat is fully furnished, so you won''t need to buy a bed.', '这套公寓家具齐全,所以你不用买床。', 'furnished');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unfurnished-1', 'unfurnished', 'It''s cheaper because it''s unfurnished, but you''ll need to buy your own sofa.', '它不带家具,所以更便宜,但你得自己买沙发。', 'unfurnished');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('apartment-1', 'apartment', 'I''m looking for a two-bedroom apartment close to the city centre.', '我在找一套靠近市中心的两居室公寓。', 'apartment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flat-1', 'flat', 'My friend and I share a flat above a small bakery.', '我和朋友合住在一家小面包店楼上的公寓里。', 'flat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flat-2', 'flat', 'The house has a flat roof, which often leaks in heavy rain.', '这栋房子是平屋顶,下大雨时经常漏水。', 'flat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('studio-1', 'studio', 'I rented a studio near campus because it was cheaper than a shared house.', '我在学校附近租了一间单间公寓,因为比合租房子便宜。', 'studio');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('studio-2', 'studio', 'The radio studio is on the third floor, next to the lifts.', '广播演播室在三楼,就在电梯旁边。', 'studio');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('semi-detached-1', 'semi-detached', 'They live in a semi-detached house with a small garden at the back.', '他们住在一栋半独立式房屋里,屋后有个小花园。', 'semi-detached');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('detached-house-1', 'detached-house', 'A detached house costs a lot more than a flat in this area.', '在这一带,独栋房屋比公寓贵得多。', 'detached house');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('terraced-house-1', 'terraced-house', 'Our terraced house shares walls with the neighbours on both sides.', '我们的联排房屋与两边的邻居共用墙壁。', 'terraced house');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cottage-1', 'cottage', 'We rented a small cottage in the countryside for the summer holidays.', '暑假期间我们在乡下租了一间小屋。', 'cottage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dormitory-1', 'dormitory', 'Each dormitory has four beds and a shared bathroom on the same floor.', '每间宿舍有四张床,同层有公用浴室。', 'dormitory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hall-of-residence-1', 'hall-of-residence', 'Most first-year students live in a hall of residence on campus.', '大多数大一新生住在校内的学生宿舍楼。', 'hall of residence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('homestay-1', 'homestay', 'A homestay is a good way to practise English with a local family.', '家庭寄宿是和当地家庭一起练习英语的好方式。', 'homestay');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('host-family-1', 'host-family', 'My host family picked me up from the airport and cooked me dinner.', '我的寄宿家庭到机场接我,还给我做了晚饭。', 'host family');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suburb-1', 'suburb', 'We moved to a quiet suburb about thirty minutes from the city centre.', '我们搬到了一个安静的郊区,距离市中心大约三十分钟。', 'suburb');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outskirts-1', 'outskirts', 'The new hospital is on the outskirts of town, near the motorway.', '新医院在市郊,靠近高速公路。', 'outskirts');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('neighbourhood-1', 'neighbourhood', 'It''s a friendly neighbourhood with plenty of shops and a small park.', '这是一个氛围友好的社区,有很多商店和一个小公园。', 'neighbourhood');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amenity-1', 'amenity', 'The nearest amenities, such as shops and a bank, are within walking distance.', '最近的商店、银行等便利设施走路就能到。', 'amenities');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('convenience-1', 'convenience', 'For your convenience, we''ve put a map of the area in every room.', '为了方便您,我们在每个房间都放了一张周边地图。', 'convenience');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commute-1', 'commute', 'Many of our staff commute to London by train every day.', '我们很多员工每天乘火车去伦敦上班。', 'commute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commute-2', 'commute', 'My commute takes about an hour each way, so I leave home early.', '我单程通勤大约要一小时,所以很早就出门。', 'commute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('balcony-1', 'balcony', 'The bedroom has a small balcony with a lovely view of the sea.', '卧室有一个小阳台,能看到美丽的海景。', 'balcony');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('basement-1', 'basement', 'You can keep your bikes in the basement, next to the washing machines.', '你可以把自行车放在地下室,就在洗衣机旁边。', 'basement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('attic-1', 'attic', 'We turned the attic into an extra bedroom for our son.', '我们把阁楼改成了儿子的卧室。', 'attic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('corridor-1', 'corridor', 'The kitchen is at the end of the corridor, on your left.', '厨房在走廊尽头,在你的左手边。', 'corridor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('courtyard-1', 'courtyard', 'All the flats look onto a courtyard with benches and a few trees.', '所有公寓都朝向一个庭院,里面有长椅和几棵树。', 'courtyard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('driveway-1', 'driveway', 'You can park in the driveway, but please don''t block the garage.', '你可以把车停在私家车道上,但请不要挡住车库。', 'driveway');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('garage-1', 'garage', 'The house comes with a garage big enough for two cars.', '这栋房子带一个能停两辆车的车库。', 'garage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fence-1', 'fence', 'The fence between the two gardens was damaged in last week''s storm.', '两个花园之间的围栏在上周的暴风雨中损坏了。', 'fence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lounge-1', 'lounge', 'Residents can watch television or relax in the lounge on the ground floor.', '住户可以在一楼的休息室看电视或放松。', 'lounge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('en-suite-1', 'en-suite', 'Every bedroom is en-suite, so you won''t need to share a shower.', '每间卧室都带独立卫浴,所以你不用和别人共用淋浴。', 'en-suite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shared-bathroom-1', 'shared-bathroom', 'The cheaper rooms come with a shared bathroom at the end of the hall.', '便宜一些的房间使用走廊尽头的公用卫生间。', 'shared bathroom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('communal-1', 'communal', 'The communal kitchen must be kept clean by everyone who uses it.', '公用厨房要靠每个使用者保持干净。', 'communal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('laundry-1', 'laundry', 'The laundry is in the basement and is open until ten at night.', '洗衣房在地下室,开放到晚上十点。', 'laundry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('laundry-2', 'laundry', 'I usually do my laundry on Sunday mornings when the machines are free.', '我通常周日上午洗衣服,那时洗衣机都空着。', 'laundry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wardrobe-1', 'wardrobe', 'There''s a large wardrobe in the bedroom for your clothes and shoes.', '卧室里有一个大衣柜,可以放你的衣服和鞋子。', 'wardrobe');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mattress-1', 'mattress', 'The old mattress was so hard that I asked for a new one.', '旧床垫太硬了,所以我要求换一张新的。', 'mattress');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pillowcase-1', 'pillowcase', 'Clean sheets and pillowcases are provided once a week.', '每周提供一次干净的床单和枕套。', 'pillowcases');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blanket-1', 'blanket', 'You''ll find an extra blanket in the cupboard if you get cold.', '如果觉得冷,橱柜里还有一条毯子。', 'blanket');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('duvet-1', 'duvet', 'Please bring your own duvet, as bedding isn''t provided.', '请自带被子,这里不提供床上用品。', 'duvet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('curtain-1', 'curtain', 'The new curtains keep out the light from the street lamps.', '新窗帘能挡住路灯的光。', 'curtains');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('microwave-1', 'microwave', 'There''s a microwave in the kitchen, but students must bring their own plates.', '厨房里有微波炉,但学生要自带盘子。', 'microwave');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('refrigerator-1', 'refrigerator', 'Please label your food before you put it in the shared refrigerator.', '把食物放进公用冰箱前,请先贴上标签。', 'refrigerator');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dishwasher-1', 'dishwasher', 'The dishwasher isn''t working, so we''ll have to wash everything by hand.', '洗碗机坏了,所以我们只能全部手洗。', 'dishwasher');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vacuum-cleaner-1', 'vacuum-cleaner', 'You can borrow a vacuum cleaner from the office on the ground floor.', '你可以到一楼办公室借吸尘器。', 'vacuum cleaner');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heater-1', 'heater', 'The small heater in the bedroom uses a lot of electricity.', '卧室里的小取暖器很费电。', 'heater');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('central-heating-1', 'central-heating', 'The flat has central heating, so it stays warm all winter.', '这套公寓有集中供暖,所以整个冬天都很暖和。', 'central heating');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('air-conditioning-1', 'air-conditioning', 'All the rooms have air conditioning, which is useful in hot weather.', '所有房间都有空调,天热时很有用。', 'air conditioning');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('socket-1', 'socket', 'There''s only one socket in the room, so I bought an extension lead.', '房间里只有一个插座,所以我买了一个接线板。', 'socket');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plumber-1', 'plumber', 'We called a plumber because water was coming through the kitchen ceiling.', '水从厨房天花板渗下来,所以我们叫了水管工。', 'plumber');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('leak-1', 'leak', 'There''s a leak under the sink, so the floor is always wet.', '水槽下面漏水,所以地板总是湿的。', 'leak');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('leak-2', 'leak', 'The roof leaks whenever it rains, so we''ve put a bucket upstairs.', '一下雨屋顶就漏水,所以我们在楼上放了个桶。', 'leaks');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('maintenance-1', 'maintenance', 'Please report any maintenance problems to the office as soon as possible.', '如有任何需要维修的问题,请尽快告知办公室。', 'maintenance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('repair-1', 'repair', 'The landlord must pay for any repairs to the roof.', '屋顶的任何修理费用都必须由房东支付。', 'repairs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('repair-2', 'repair', 'Someone will come to repair the washing machine on Tuesday morning.', '周二上午会有人来修洗衣机。', 'repair');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inspection-1', 'inspection', 'The landlord will carry out an inspection of the flat every six months.', '房东每六个月会检查一次公寓。', 'inspection');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spacious-1', 'spacious', 'The living room is spacious enough for a large sofa and a dining table.', '客厅很宽敞,放得下一张大沙发和一张餐桌。', 'spacious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cosy-1', 'cosy', 'It''s only a small room, but it feels warm and cosy in winter.', '房间虽小,但冬天感觉温暖又舒适。', 'cosy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('parking-space-1', 'parking-space', 'Each flat comes with one parking space behind the building.', '每套公寓都配有一个位于楼后的停车位。', 'parking space');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('postcode-1', 'postcode', 'Could you give me your postcode so I can find the address?', '能告诉我你的邮编吗?这样我好查地址。', 'postcode');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reference-1', 'reference', 'The agency asked for a reference from my previous landlord.', '中介要求我提供前房东的推荐信。', 'reference');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reference-2', 'reference', 'Please keep this guide for future reference during your stay here.', '住在这里期间,请保留这份指南以便日后参考。', 'reference');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bedsit-1', 'bedsit', 'As a student, I lived in a tiny bedsit with a cooker beside the bed.', '上学时我住在一间很小的单间出租房里,灶具就在床边。', 'bedsit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flatmate-1', 'flatmate', 'My flatmate and I take turns to clean the kitchen and bathroom.', '我和合租室友轮流打扫厨房和浴室。', 'flatmate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suite-1', 'suite', 'The hotel upgraded us to a suite with a separate living room.', '酒店把我们升级到了带独立客厅的套房。', 'suite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fireplace-1', 'fireplace', 'The cottage has an old fireplace, but it''s no longer safe to use.', '小屋里有一个旧壁炉,但已经不能安全使用了。', 'fireplace');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('radiator-1', 'radiator', 'The radiator in my room isn''t getting hot, even with the heating on.', '即使开了暖气,我房间的暖气片也不热。', 'radiator');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foyer-1', 'foyer', 'Please wait for me in the foyer, just inside the main doors.', '请在门厅等我,一进正门就是。', 'foyer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('storeroom-1', 'storeroom', 'Residents can leave their suitcases in the storeroom during the holidays.', '假期里住户可以把行李箱放在储藏室。', 'storeroom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lift-1', 'lift', 'The lift is out of order, so you''ll have to use the stairs.', '电梯坏了,所以你只能走楼梯。', 'lift');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shutter-1', 'shutter', 'We close the shutters at night to keep out the noise.', '我们晚上会关上百叶窗,挡住外面的噪音。', 'shutters');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cupboard-1', 'cupboard', 'The plates and glasses are in the cupboard above the sink.', '盘子和杯子在水槽上方的橱柜里。', 'cupboard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('armchair-1', 'armchair', 'There''s a comfortable armchair next to the window for reading.', '窗边有一把舒服的扶手椅,可以坐着看书。', 'armchair');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stool-1', 'stool', 'The kitchen has a narrow counter with two stools.', '厨房有一个窄窄的吧台,配了两张凳子。', 'stools');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bedspread-1', 'bedspread', 'The guest room has a matching bedspread and curtains in pale blue.', '客房的床罩和窗帘是配套的淡蓝色。', 'bedspread');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('washbasin-1', 'washbasin', 'Each room has its own washbasin, but the toilets are shared.', '每个房间都有自己的洗脸盆,但厕所是公用的。', 'washbasin');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lavatory-1', 'lavatory', 'The only lavatory is on the ground floor, next to the back door.', '唯一的厕所在一楼,就在后门旁边。', 'lavatory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('toaster-1', 'toaster', 'Please don''t use the toaster in your room because of the smoke alarm.', '房间里有烟雾报警器,请不要在房间里使用烤面包机。', 'toaster');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('letting-agency-1', 'letting-agency', 'I found this flat through a letting agency near the university.', '我是通过大学附近的一家租房中介找到这套公寓的。', 'letting agency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('real-estate-agency-1', 'real-estate-agency', 'A real estate agency can help you find a house to buy.', '房地产中介可以帮你找到想买的房子。', 'real estate agency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('studio-apartment-1', 'studio-apartment', 'A studio apartment has just one main room for sleeping, cooking and relaxing.', '单间公寓只有一个主要房间,睡觉、做饭和休息都在里面。', 'studio apartment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tenancy-agreement-1', 'tenancy-agreement', 'Read the tenancy agreement carefully before you sign it and pay the deposit.', '签字和付押金之前,请仔细阅读租赁合同。', 'tenancy agreement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plug-1', 'plug', 'My laptop charger has a different plug, so I need an adapter.', '我的笔记本充电器插头不一样,所以需要一个转换器。', 'plug');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plug-2', 'plug', 'Just plug the fridge in and wait an hour before using it.', '给冰箱接通电源后,等一小时再用。', 'plug');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lawn-1', 'lawn', 'Tenants are responsible for cutting the lawn during the summer months.', '夏季由租户负责修剪草坪。', 'lawn');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('terrace-1', 'terrace', 'We often eat outside on the terrace when the weather is warm.', '天气暖和时,我们常在露台上吃饭。', 'terrace');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('terrace-2', 'terrace', 'Our house is in the middle of a long terrace of brick homes.', '我们家位于一长排砖砌排屋的中间。', 'terrace');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('porch-1', 'porch', 'You can leave the parcel in the porch if nobody answers the door.', '如果没人应门,可以把包裹放在门廊里。', 'porch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('closet-1', 'closet', 'The flat has a closet in the hall for coats and boots.', '公寓门厅有一个壁橱,可以放外套和靴子。', 'closet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cellar-1', 'cellar', 'The house has a cellar, but it''s too damp for storing anything.', '这栋房子有地窖,但太潮湿,放不了东西。', 'cellar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cushion-1', 'cushion', 'We bought some bright cushions to make the old sofa look better.', '我们买了一些鲜艳的靠垫,让旧沙发好看一点。', 'cushions');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bungalow-1', 'bungalow', 'My grandparents moved to a bungalow because they can''t manage the stairs.', '我的祖父母搬到了平房,因为他们爬不动楼梯了。', 'bungalow');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mansion-1', 'mansion', 'The old mansion on the hill has over twenty bedrooms and its own lake.', '山上那座老豪宅有二十多间卧室,还有自己的湖。', 'mansion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('roommate-1', 'roommate', 'My roommate goes to bed early, so I study in the library at night.', '我的室友睡得早,所以我晚上去图书馆学习。', 'roommate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tile-1', 'tile', 'Several bathroom tiles are cracked and need replacing.', '浴室有几块瓷砖裂了,需要更换。', 'tiles');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bulb-1', 'bulb', 'The bulb in the hall has gone, so we need a new one.', '门厅的灯泡坏了,所以我们需要换个新的。', 'bulb');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bulb-2', 'bulb', 'We planted some tulip bulbs along the fence last autumn.', '去年秋天我们沿着围栏种了一些郁金香球茎。', 'bulbs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mould-1', 'mould', 'There''s mould on the bathroom ceiling because the room has no window.', '浴室没有窗户,所以天花板上长了霉。', 'mould');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mould-2', 'mould', 'The workers pour the hot metal into a mould and leave it to cool.', '工人把热金属倒入模具,然后让它冷却。', 'mould');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('itinerary-1', 'itinerary', 'The travel agent will email you a full itinerary before you leave.', '旅行社会在你出发前把完整的行程表发邮件给你。', 'itinerary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('destination-1', 'destination', 'Spain is still the most popular destination for our summer tours.', '西班牙仍然是我们夏季旅行团最受欢迎的目的地。', 'destination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('departure-1', 'departure', 'Please arrive at the airport two hours before your departure.', '请在出发前两小时到达机场。', 'departure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arrival-1', 'arrival', 'Please check in at the reception desk on arrival at the hotel.', '到达酒店后,请在前台办理入住。', 'arrival');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reservation-1', 'reservation', 'I''d like to make a reservation for two nights in early May.', '我想预订五月初的两晚住宿。', 'reservation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('book-1', 'book', 'You should book your train tickets early to get a better price.', '你应该早点预订火车票,这样价格更便宜。', 'book');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('confirm-1', 'confirm', 'Please call us two days before the trip to confirm your place.', '请在出行前两天致电我们,确认你的名额。', 'confirm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cancellation-1', 'cancellation', 'There''s a small charge for any cancellation made after Friday.', '周五之后取消预订要收取少量费用。', 'cancellation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('refund-1', 'refund', 'You can get a full refund if you cancel within seven days.', '七天内取消可以获得全额退款。', 'refund');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('refund-2', 'refund', 'The airline agreed to refund our tickets after the flight was cancelled.', '航班取消后,航空公司同意退还我们的机票钱。', 'refund');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brochure-1', 'brochure', 'This brochure lists all the hotels and day trips we offer.', '这本宣传册列出了我们提供的所有酒店和一日游。', 'brochure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('package-tour-1', 'package-tour', 'A package tour usually includes your flights, hotel and some meals.', '跟团游通常包含机票、酒店和部分餐食。', 'package tour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('excursion-1', 'excursion', 'There''s an optional excursion to the old town on the third day.', '第三天有一个去老城的自选短途游。', 'excursion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sightseeing-1', 'sightseeing', 'We spent the morning sightseeing and the afternoon relaxing on the beach.', '我们上午观光,下午在海滩上放松。', 'sightseeing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('guided-tour-1', 'guided-tour', 'The guided tour of the castle starts at eleven and lasts an hour.', '城堡的导览游十一点开始,持续一小时。', 'guided tour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('backpacker-1', 'backpacker', 'The town is popular with young backpackers because food and rooms are cheap.', '这个小镇很受年轻背包客欢迎,因为吃住都便宜。', 'backpackers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hostel-1', 'hostel', 'We stayed in a cheap hostel with shared rooms near the bus station.', '我们住在汽车站附近一家便宜的旅舍,房间是合住的。', 'hostel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bed-and-breakfast-1', 'bed-and-breakfast', 'We stayed at a small bed and breakfast run by a local couple.', '我们住在一家由当地夫妇经营的小民宿。', 'bed and breakfast');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('campsite-1', 'campsite', 'The campsite has hot showers and a small shop near the entrance.', '营地有热水淋浴,入口附近还有一家小商店。', 'campsite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('caravan-1', 'caravan', 'We hired a caravan and drove along the coast for two weeks.', '我们租了一辆房车,沿着海岸开了两周。', 'caravan');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cabin-1', 'cabin', 'Each cabin on the ship has two beds and a small window.', '船上每间船舱都有两张床和一扇小窗。', 'cabin');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cabin-2', 'cabin', 'We stayed in a wooden cabin beside the lake for the weekend.', '周末我们住在湖边的一间木屋里。', 'cabin');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('single-room-1', 'single-room', 'A single room costs £60 a night, including breakfast.', '单人间每晚 60 英镑,含早餐。', 'single room');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('double-room-1', 'double-room', 'We''d like a double room with a view of the garden, please.', '我们想要一间能看到花园的大床双人间。', 'double room');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('twin-room-1', 'twin-room', 'My friend and I asked for a twin room with separate beds.', '我和朋友要了一间有两张床的双人间。', 'twin room');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vacancy-1', 'vacancy', 'Sorry, the hotel has no vacancies during the festival next week.', '抱歉,下周节日期间酒店没有空房。', 'vacancies');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('check-in-1', 'check-in', 'Check-in opens two hours before the flight and closes forty minutes before it.', '值机在航班起飞前两小时开放,起飞前四十分钟关闭。', 'Check-in');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('check-out-1', 'check-out', 'Check-out is at eleven, but you can leave your bags at the desk.', '退房时间是十一点,但你可以把包寄存在前台。', 'Check-out');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reception-1', 'reception', 'Please hand in your room key at reception when you leave.', '离开时请把房间钥匙交到前台。', 'reception');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reception-2', 'reception', 'The wedding reception will be held in the hotel''s main hall.', '婚礼招待会将在酒店的主厅举行。', 'reception');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('receptionist-1', 'receptionist', 'The receptionist gave us a map and showed us where to park.', '前台接待员给了我们一张地图,还告诉我们在哪里停车。', 'receptionist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('luggage-1', 'luggage', 'You can leave your luggage in this room until your bus arrives.', '在你的巴士到来之前,可以把行李放在这个房间。', 'luggage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('baggage-allowance-1', 'baggage-allowance', 'Your baggage allowance on this flight is twenty kilos per passenger.', '这趟航班的行李限额是每位乘客二十公斤。', 'baggage allowance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carry-on-1', 'carry-on', 'You may take one carry-on bag and a small handbag on the plane.', '你可以带一个随身行李包和一个小手提包上飞机。', 'carry-on');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('passport-1', 'passport', 'Make sure your passport is valid for at least six months.', '请确保你的护照至少还有六个月有效期。', 'passport');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('visa-1', 'visa', 'Students from some countries need a visa before they can enter.', '来自部分国家的学生入境前需要办理签证。', 'visa');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('customs-1', 'customs', 'We had to open our suitcases when we went through customs.', '过海关时,我们不得不打开行李箱。', 'customs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('immigration-1', 'immigration', 'There was a long queue at immigration when we landed in Sydney.', '我们在悉尼降落后,入境检查处排着长队。', 'immigration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('boarding-pass-1', 'boarding-pass', 'Please have your boarding pass and passport ready at the gate.', '请在登机口准备好登机牌和护照。', 'boarding pass');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gate-1', 'gate', 'Your flight to Rome will now leave from gate twelve.', '你飞往罗马的航班现在改从十二号登机口出发。', 'gate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('terminal-1', 'terminal', 'International flights leave from the new terminal on the other side of the airport.', '国际航班从机场另一侧的新航站楼出发。', 'terminal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flight-1', 'flight', 'My flight to Berlin leaves at seven tomorrow morning.', '我飞往柏林的航班明早七点起飞。', 'flight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('delay-1', 'delay', 'There''s a two-hour delay because of heavy snow at the airport.', '由于机场大雪,航班延误了两小时。', 'delay');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('delay-2', 'delay', 'Bad weather may delay the ferry, so please check before you leave.', '恶劣天气可能导致渡轮延误,所以出发前请查询。', 'delay');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transfer-1', 'transfer', 'The hotel offers a free transfer between the airport and the city centre.', '酒店提供机场和市中心之间的免费接送。', 'transfer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transfer-2', 'transfer', 'You''ll need to transfer to another train at the next station.', '你需要在下一站换乘另一趟火车。', 'transfer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shuttle-bus-1', 'shuttle-bus', 'A free shuttle bus runs between the terminal and the car park.', '航站楼和停车场之间有免费的接驳巴士。', 'shuttle bus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coach-1', 'coach', 'The coach to Oxford leaves from the bus station every half hour.', '开往牛津的长途汽车每半小时从汽车站发车。', 'coach');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coach-2', 'coach', 'Our swimming coach makes us train three times a week.', '我们的游泳教练要我们每周训练三次。', 'coach');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ferry-1', 'ferry', 'The ferry to the island takes about forty minutes each way.', '去岛上的渡轮单程大约四十分钟。', 'ferry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cruise-1', 'cruise', 'They went on a two-week cruise around the Mediterranean last summer.', '去年夏天他们坐游轮环游了地中海,为期两周。', 'cruise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('platform-1', 'platform', 'The train to Manchester will now leave from platform six.', '开往曼彻斯特的列车现在改从六号站台发车。', 'platform');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('timetable-1', 'timetable', 'Check the bus timetable because there are fewer services on Sundays.', '看看公交时刻表,因为周日的班次较少。', 'timetable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('single-ticket-1', 'single-ticket', 'A single ticket to the city centre costs two pounds fifty.', '到市中心的单程票是两英镑五十便士。', 'single ticket');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('return-ticket-1', 'return-ticket', 'A return ticket is usually cheaper than buying two singles.', '买往返票通常比买两张单程票便宜。', 'return ticket');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fare-1', 'fare', 'The bus fare has gone up by twenty pence since January.', '公交车费从一月起涨了二十便士。', 'fare');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('concession-1', 'concession', 'Students and pensioners can get a concession if they show their cards.', '学生和退休人员出示证件可享受优惠票价。', 'concession');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('season-ticket-1', 'season-ticket', 'A monthly season ticket saves me quite a lot on my journey to work.', '买月票让我上班路费省了不少。', 'season ticket');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('underground-1', 'underground', 'The quickest way to get to the museum is by underground.', '去博物馆最快的方式是坐地铁。', 'underground');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subway-1', 'subway', 'Take the subway to Central Park and then walk for five minutes.', '乘地铁到中央公园,然后步行五分钟。', 'subway');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subway-2', 'subway', 'Use the subway under the road to reach the other side safely.', '走马路下面的地下通道可以安全到达对面。', 'subway');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tram-1', 'tram', 'You can take the tram from the station directly to the seafront.', '你可以从车站直接乘有轨电车到海滨。', 'tram');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cab-1', 'cab', 'It was raining heavily, so we took a cab back to the hotel.', '雨下得很大,所以我们打车回了酒店。', 'cab');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('motorway-1', 'motorway', 'Stay on the motorway until you see the sign for the airport.', '沿高速公路一直开,直到看到机场的指示牌。', 'motorway');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lane-1', 'lane', 'Keep to the left lane when you reach the end of the bridge.', '到桥尽头时,请靠左侧车道行驶。', 'lane');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lane-2', 'lane', 'The farm is at the end of a narrow lane behind the church.', '农场在教堂后面一条窄巷的尽头。', 'lane');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('junction-1', 'junction', 'Turn right at the next junction and the hotel is straight ahead.', '在下一个路口右转,酒店就在正前方。', 'junction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('roundabout-1', 'roundabout', 'Go straight over the roundabout and take the second road on the left.', '直行穿过环岛,然后走左边第二条路。', 'roundabout');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crossroads-1', 'crossroads', 'Turn left at the crossroads, just after the petrol station.', '过了加油站,在十字路口左转。', 'crossroads');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('traffic-lights-1', 'traffic-lights', 'Go straight on at the traffic lights and the bank is on your right.', '在红绿灯处直行,银行就在你右边。', 'traffic lights');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pedestrian-1', 'pedestrian', 'This part of the town centre is open to pedestrians only.', '市中心的这一部分只允许行人通行。', 'pedestrians');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pavement-1', 'pavement', 'Please don''t leave your bike on the pavement outside the shop.', '请不要把自行车停在商店外的人行道上。', 'pavement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('detour-1', 'detour', 'The bridge is closed, so we had to make a long detour.', '桥封闭了,所以我们只好绕了很长一段路。', 'detour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('toll-1', 'toll', 'Drivers have to pay a small toll to cross the new bridge.', '司机过这座新桥要交一小笔通行费。', 'toll');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('landmark-1', 'landmark', 'The clock tower is the town''s best-known landmark and is easy to find.', '钟楼是这个小镇最著名的地标,很容易找到。', 'landmark');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('monument-1', 'monument', 'The monument in the square was built to remember the city''s founder.', '广场上的纪念碑是为纪念这座城市的创建者而建的。', 'monument');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('souvenir-1', 'souvenir', 'I bought a small painting as a souvenir of my trip to Peru.', '我买了一幅小画,作为秘鲁之行的纪念品。', 'souvenir');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('currency-1', 'currency', 'You can change your money into local currency at the airport.', '你可以在机场把钱换成当地货币。', 'currency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exchange-rate-1', 'exchange-rate', 'The exchange rate is usually better at a bank than at a hotel.', '银行的汇率通常比酒店的更划算。', 'exchange rate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('insurance-1', 'insurance', 'Don''t forget to buy travel insurance before you go skiing.', '去滑雪之前别忘了买旅行保险。', 'insurance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sunscreen-1', 'sunscreen', 'Bring a hat and some sunscreen, as there''s little shade on the island.', '带上帽子和防晒霜,因为岛上没什么阴凉的地方。', 'sunscreen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('first-aid-kit-1', 'first-aid-kit', 'Each group leader carries a first aid kit in case of accidents.', '每位领队都带着急救包,以防发生意外。', 'first aid kit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('binoculars-1', 'binoculars', 'Remember to bring binoculars if you want to watch the birds.', '如果想观鸟,记得带双筒望远镜。', 'binoculars');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('motel-1', 'motel', 'We stopped at a roadside motel because we were too tired to drive.', '我们太累开不动了,就在路边的汽车旅馆停了下来。', 'motel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inn-1', 'inn', 'We had lunch at an old inn in the middle of the village.', '我们在村子中央的一家老旅馆吃了午饭。', 'inn');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lodge-1', 'lodge', 'The ski lodge is only a short walk from the slopes.', '这家滑雪旅舍离雪道只有几步路。', 'lodge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('castle-1', 'castle', 'The castle is open to visitors every day except Monday.', '这座城堡除周一外每天对游客开放。', 'castle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tent-1', 'tent', 'Put up your tent before dark, as there are no lights at the site.', '天黑前把帐篷搭好,因为营地没有灯。', 'tent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('torch-1', 'torch', 'You''ll need a torch because the path to the beach has no lights.', '你需要带手电筒,因为去海滩的路上没有灯。', 'torch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('torch-2', 'torch', 'Runners carried the Olympic torch through the city centre this morning.', '今天上午,跑步者手持奥运火炬穿过市中心。', 'torch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flashlight-1', 'flashlight', 'Keep a flashlight in the car in case you break down at night.', '在车里放一个手电筒,以防夜里抛锚。', 'flashlight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('metro-1', 'metro', 'The metro runs until midnight and is the cheapest way to get around.', '地铁运行到午夜,是最便宜的出行方式。', 'metro');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tube-1', 'tube', 'We took the tube from Victoria Station to the British Museum.', '我们从维多利亚站坐地铁去了大英博物馆。', 'tube');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tube-2', 'tube', 'The water passes through a thin plastic tube into the tank.', '水通过一根细塑料管流入水箱。', 'tube');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('yacht-1', 'yacht', 'You can hire a yacht with a crew for a day at the harbour.', '你可以在港口租一艘配船员的游艇玩一天。', 'yacht');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('embark-1', 'embark', 'Passengers may embark from two o''clock, and the ship sails at five.', '乘客两点可以开始登船,船五点起航。', 'embark');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('takeoff-1', 'takeoff', 'Please turn off your phones and fasten your seatbelts before takeoff.', '起飞前请关闭手机并系好安全带。', 'takeoff');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('landing-1', 'landing', 'The plane made a smooth landing in spite of the strong wind.', '尽管风很大,飞机还是平稳着陆了。', 'landing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('landing-2', 'landing', 'The bathroom is on the first-floor landing, right next to the stairs.', '浴室在二楼的楼梯平台上,就在楼梯旁边。', 'landing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('berth-1', 'berth', 'I booked a lower berth on the night train to Edinburgh.', '我订了去爱丁堡夜车的下铺。', 'berth');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sleeper-1', 'sleeper', 'We took the overnight sleeper from London and arrived in Scotland at dawn.', '我们从伦敦坐夜间卧铺列车,黎明时到达苏格兰。', 'sleeper');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('attendant-1', 'attendant', 'Ask the flight attendant if you need another blanket or a drink.', '如果还需要毯子或饮料,可以问空乘人员。', 'attendant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inspector-1', 'inspector', 'The ticket inspector fined me because I had forgotten my student card.', '查票员罚了我的款,因为我忘了带学生证。', 'inspector');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stopover-1', 'stopover', 'There''s a three-hour stopover in Dubai on the way to Australia.', '去澳大利亚途中要在迪拜停留三小时。', 'stopover');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('avenue-1', 'avenue', 'The theatre is on Park Avenue, opposite the main post office.', '剧院在公园大街,就在邮政总局对面。', 'Avenue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('boulevard-1', 'boulevard', 'We walked along a wide boulevard lined with cafés and old trees.', '我们沿着一条宽阔的林荫大道走,路边都是咖啡馆和老树。', 'boulevard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alley-1', 'alley', 'The little café is hidden in an alley behind the market.', '这家小咖啡馆藏在市场后面的小巷里。', 'alley');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intersection-1', 'intersection', 'Turn left at the next intersection and look for a blue building.', '在下一个十字路口左转,找一栋蓝色的建筑。', 'intersection');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crosswalk-1', 'crosswalk', 'Always use the crosswalk when you get across this busy street.', '过这条繁忙的街道时,一定要走人行横道。', 'crosswalk');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scuba-diving-1', 'scuba-diving', 'You''ll need a short training course before you can go scuba diving.', '去水肺潜水之前,你需要上一个短期培训班。', 'scuba diving');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hang-gliding-1', 'hang-gliding', 'Hang-gliding is a popular activity on the hills above the town.', '悬挂滑翔是小镇上方山丘上一项很受欢迎的活动。', 'Hang-gliding');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('youth-hostel-1', 'youth-hostel', 'The youth hostel offers cheap beds and a shared kitchen for guests.', '这家青年旅舍为客人提供便宜的床位和公用厨房。', 'youth hostel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('charter-flight-1', 'charter-flight', 'The tour company has arranged a charter flight directly to the island.', '旅行社安排了一架直飞该岛的包机。', 'charter flight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('economy-class-1', 'economy-class', 'Seats in economy class are narrow, but the tickets are much cheaper.', '经济舱座位很窄,但机票便宜得多。', 'economy class');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('driving-licence-1', 'driving-licence', 'You must show your driving licence when you hire a car.', '租车时必须出示驾照。', 'driving licence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pedestrian-crossing-1', 'pedestrian-crossing', 'Stop at the pedestrian crossing and let people get across the road.', '在人行横道前停车,让行人过马路。', 'pedestrian crossing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cycle-lane-1', 'cycle-lane', 'A new cycle lane now runs from the station to the university.', '现在有一条新的自行车道从车站通到大学。', 'cycle lane');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ring-road-1', 'ring-road', 'Take the ring road if you want to avoid the traffic in town.', '如果想避开市内的拥堵,就走环路。', 'ring road');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dual-carriageway-1', 'dual-carriageway', 'Turn left at the roundabout, then follow the dual carriageway for two miles.', '在环岛左转,然后沿双向分隔车道公路走两英里。', 'dual carriageway');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('t-junction-1', 't-junction', 'Go to the end of this road and turn right at the T-junction.', '走到这条路的尽头,在丁字路口右转。', 'T-junction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('place-of-interest-1', 'place-of-interest', 'The guidebook lists every place of interest within an hour of the city.', '指南列出了距离这座城市一小时车程内的所有名胜。', 'place of interest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overseas-1', 'overseas', 'More of our customers are now choosing overseas holidays in winter.', '现在越来越多的顾客在冬天选择去海外度假。', 'overseas');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overseas-2', 'overseas', 'I''d like to work overseas for a year after I graduate.', '我想毕业后去海外工作一年。', 'overseas');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aisle-1', 'aisle', 'Would you prefer a seat by the window or on the aisle?', '您想要靠窗的座位还是靠过道的座位?', 'aisle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tyre-1', 'tyre', 'We got a flat tyre on the way and had to call for help.', '我们路上爆胎了,只好打电话求助。', 'tyre');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('baggage-1', 'baggage', 'Please collect your baggage from the belt in the arrivals hall.', '请到到达大厅的传送带提取行李。', 'baggage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suitcase-1', 'suitcase', 'My suitcase didn''t arrive with me, so I reported it at the desk.', '我的手提箱没有和我一起到,所以我去服务台报告了。', 'suitcase');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trolley-1', 'trolley', 'You can use a trolley to carry your bags to the car park.', '你可以用手推车把行李运到停车场。', 'trolley');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lobby-1', 'lobby', 'Let''s meet in the hotel lobby at nine and walk from there.', '我们九点在酒店大堂见面,然后从那里走过去。', 'lobby');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lobby-2', 'lobby', 'Farmers are trying to lobby the government for more financial support.', '农民正在游说政府提供更多资金支持。', 'lobby');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('booth-1', 'booth', 'You can buy tickets for the boat trip at the booth by the pier.', '你可以在码头旁的售票亭买游船票。', 'booth');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transit-1', 'transit', 'Your bags may be delayed if you''re in transit through a busy airport.', '如果你在繁忙的机场中转,行李可能会延误。', 'transit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('escort-1', 'escort', 'A member of staff will escort you to the gate in a wheelchair.', '工作人员会用轮椅护送你到登机口。', 'escort');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hike-1', 'hike', 'We went for a long hike in the hills on our last day.', '最后一天,我们去山里长途徒步了一次。', 'hike');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fortnight-1', 'fortnight', 'We''re going to Greece for a fortnight at the end of August.', '八月底我们要去希腊待两周。', 'fortnight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('traveller-1', 'traveller', 'This café is a favourite with travellers waiting for the morning ferry.', '这家咖啡馆很受等早班渡轮的旅行者喜爱。', 'travellers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('guide-1', 'guide', 'Our guide told us a lot about the history of the old town.', '导游给我们讲了很多老城的历史。', 'guide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('guide-2', 'guide', 'Small lights along the floor guide visitors through the dark cave.', '地面上的小灯引导游客穿过黑暗的洞穴。', 'guide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dock-1', 'dock', 'We walked down to the dock to watch the fishing boats come in.', '我们走到码头,看渔船进港。', 'dock');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dock-2', 'dock', 'The ship will dock at eight, so you''ll have all day to explore.', '船八点靠岸,所以你有一整天时间游览。', 'dock');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('layout-1', 'layout', 'The layout of the museum is confusing, so take a map with you.', '博物馆的布局容易让人迷路,所以带上一张地图。', 'layout');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('entrance-1', 'entrance', 'The main entrance is on the north side of the building.', '正门在大楼的北侧。', 'entrance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exit-1', 'exit', 'The nearest exit is at the back of the hall, behind the stage.', '最近的出口在大厅后部,舞台后面。', 'exit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('opposite-1', 'opposite', 'The ticket office is directly opposite the main entrance of the park.', '售票处就在公园正门的正对面。', 'opposite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('opposite-2', 'opposite', 'Cross the road and wait for the bus on the opposite side.', '过马路,在对面等公交车。', 'opposite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adjacent-1', 'adjacent', 'The car park is adjacent to the museum, so you won''t have far to walk.', '停车场紧邻博物馆,所以不用走很远。', 'adjacent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diagonally-1', 'diagonally', 'The café is diagonally across from the library, on the corner of the square.', '咖啡馆在图书馆的斜对面,位于广场的一角。', 'diagonally');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clockwise-1', 'clockwise', 'Walk clockwise around the lake and you''ll reach the boat house first.', '沿顺时针方向绕湖走,你会先到船屋。', 'clockwise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('anticlockwise-1', 'anticlockwise', 'The route goes anticlockwise round the park, starting from the south gate.', '路线从南门出发,逆时针绕公园一圈。', 'anticlockwise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('north-east-1', 'north-east', 'The new sports hall is in the north-east of the campus.', '新体育馆在校园的东北部。', 'north-east');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('south-west-1', 'south-west', 'The lake is in the south-west of the park, near the café.', '湖在公园的西南部,靠近咖啡馆。', 'south-west');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bend-1', 'bend', 'Slow down here, because there''s a sharp bend just after the bridge.', '这里请减速,因为过桥后有一个急转弯。', 'bend');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('track-1', 'track', 'Follow the track through the woods until you reach the river.', '沿着小道穿过树林,一直走到河边。', 'track');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trail-1', 'trail', 'The coastal trail takes about three hours and has wonderful views.', '这条海岸步道大约要走三小时,沿途风景很美。', 'trail');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('footpath-1', 'footpath', 'A footpath leads from the car park down to the waterfall.', '一条人行小径从停车场通向瀑布。', 'footpath');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('car-park-1', 'car-park', 'The car park behind the theatre is free after six o''clock.', '剧院后面的停车场六点以后免费。', 'car park');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('picnic-area-1', 'picnic-area', 'There''s a picnic area with tables beside the pond.', '池塘边有一个摆着桌子的野餐区。', 'picnic area');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('viewpoint-1', 'viewpoint', 'From the viewpoint at the top, you can see the whole valley.', '从山顶的观景点可以看到整个山谷。', 'viewpoint');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lighthouse-1', 'lighthouse', 'The old lighthouse is now a small museum about life at sea.', '这座旧灯塔现在是一座介绍海上生活的小博物馆。', 'lighthouse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pier-1', 'pier', 'You can catch the boat from the end of the pier.', '你可以在栈桥尽头乘船。', 'pier');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('harbour-1', 'harbour', 'Fishing boats were coming into the harbour as we had breakfast.', '我们吃早餐时,渔船正驶入港口。', 'harbour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('windmill-1', 'windmill', 'The old windmill on the hill was once used to grind flour.', '山上那座旧风车过去用来磨面粉。', 'windmill');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('barn-1', 'barn', 'The farm has turned its old barn into a café for visitors.', '农场把旧谷仓改成了接待游客的咖啡馆。', 'barn');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('orchard-1', 'orchard', 'Visitors can pick their own apples in the orchard during September.', '九月游客可以在果园里自己摘苹果。', 'orchard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pond-1', 'pond', 'There are ducks on the pond in front of the old farmhouse.', '老农舍前的池塘里有鸭子。', 'pond');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fountain-1', 'fountain', 'Let''s meet by the fountain in the middle of the square.', '我们在广场中央的喷泉旁见面吧。', 'fountain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('statue-1', 'statue', 'The statue at the entrance shows the man who started the school.', '入口处的雕像塑的是这所学校的创办人。', 'statue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gallery-1', 'gallery', 'The art gallery is free, but there''s a charge for special exhibitions.', '美术馆免费参观,但特别展览要收费。', 'gallery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('auditorium-1', 'auditorium', 'The talk has moved to the main auditorium because so many people signed up.', '报名的人太多,讲座改到了主礼堂。', 'auditorium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pavilion-1', 'pavilion', 'There''s a small pavilion by the lake where you can sit in the shade.', '湖边有一座小亭子,你可以坐在里面乘凉。', 'pavilion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('block-1', 'block', 'The post office is two blocks from here, on your left.', '邮局离这里两个街区,在你的左边。', 'blocks');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('block-2', 'block', 'Fallen trees may block the road after a heavy storm.', '暴风雨过后,倒下的树可能会挡住道路。', 'block');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gutter-1', 'gutter', 'Leaves had filled the gutter, so the rain ran across the road.', '落叶堵满了排水沟,所以雨水流得满路都是。', 'gutter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('moat-1', 'moat', 'You have to cross a wooden bridge over the moat to enter the castle.', '要进入城堡,得走过护城河上的一座木桥。', 'moat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arrow-1', 'arrow', 'Just follow the red arrows on the wall to find the exit.', '只要跟着墙上的红色箭头走就能找到出口。', 'arrows');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('halfway-1', 'halfway', 'We stopped for lunch about halfway between London and Edinburgh.', '我们在伦敦和爱丁堡之间大约中途的地方停下来吃午饭。', 'halfway');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('underneath-1', 'underneath', 'You''ll find the toilets underneath the main stairs, next to the café.', '洗手间在主楼梯下面,紧挨着咖啡馆。', 'underneath');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cuisine-1', 'cuisine', 'The restaurant is famous for its traditional Thai cuisine and friendly service.', '这家餐厅以传统泰国菜和友好的服务闻名。', 'cuisine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('starter-1', 'starter', 'I''ll have the soup as a starter, followed by the grilled fish.', '我先点汤作为开胃菜,然后要烤鱼。', 'starter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('main-course-1', 'main-course', 'The main course comes with rice or potatoes and a small salad.', '主菜配米饭或土豆,还有一份小沙拉。', 'main course');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dessert-1', 'dessert', 'Would you like to see the dessert menu after your main meal?', '用完正餐后,您想看看甜点菜单吗?', 'dessert');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('beverage-1', 'beverage', 'Hot beverages are served in the hall during the morning break.', '上午休息时,大厅里供应热饮。', 'beverages');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('buffet-1', 'buffet', 'Breakfast is a buffet, so you can help yourself to whatever you like.', '早餐是自助餐,想吃什么可以自己取。', 'buffet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('takeaway-1', 'takeaway', 'We were too tired to cook, so we ordered a Chinese takeaway.', '我们累得不想做饭,就点了中餐外卖。', 'takeaway');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('canteen-1', 'canteen', 'The staff canteen serves hot meals from twelve until two o''clock.', '员工食堂从十二点到两点供应热餐。', 'canteen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cafeteria-1', 'cafeteria', 'You can get a cheap lunch at the cafeteria on the ground floor.', '你可以在一楼的自助餐厅吃到便宜的午餐。', 'cafeteria');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('catering-1', 'catering', 'A local company will handle the catering for the conference next month.', '下个月会议的餐饮服务由当地一家公司负责。', 'catering');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vegetarian-1', 'vegetarian', 'As a vegetarian, I find it hard to eat out in this town.', '我是素食者,在这个镇上外出吃饭很难。', 'vegetarian');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vegetarian-2', 'vegetarian', 'Does the menu include any vegetarian dishes for our guests?', '菜单上有适合我们客人的素菜吗?', 'vegetarian');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vegan-1', 'vegan', 'Our new chef offers a separate menu for vegans and people with allergies.', '新厨师为严格素食者和过敏人群提供单独的菜单。', 'vegans');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('allergy-1', 'allergy', 'Please tell the waiter if you have an allergy to nuts.', '如果你对坚果过敏,请告诉服务员。', 'allergy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dairy-1', 'dairy', 'She can''t eat dairy, so we''ll need a cake made without butter.', '她不能吃乳制品,所以我们需要一个不含黄油的蛋糕。', 'dairy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gluten-1', 'gluten', 'This bread is made without gluten and is safe for people with coeliac disease.', '这种面包不含麸质,乳糜泻患者可以放心食用。', 'gluten');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seafood-1', 'seafood', 'The town is known for its fresh seafood, especially crab and oysters.', '这个小镇以新鲜海鲜闻名,尤其是螃蟹和牡蛎。', 'seafood');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('poultry-1', 'poultry', 'The butcher sells beef and lamb as well as poultry from local farms.', '这家肉店卖牛羊肉,也卖来自当地农场的禽肉。', 'poultry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ingredient-1', 'ingredient', 'All the ingredients in our soups come from farms in the area.', '我们汤里的所有原料都来自本地农场。', 'ingredients');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recipe-1', 'recipe', 'A friend gave me her recipe for chocolate cake last weekend.', '上周末,一位朋友把她的巧克力蛋糕食谱给了我。', 'recipe');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('portion-1', 'portion', 'The portions here are huge, so one dish is enough for two people.', '这里的分量很大,一道菜够两个人吃。', 'portions');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nutrition-1', 'nutrition', 'The talk on nutrition will explain how to plan a healthy weekly menu.', '营养讲座会讲解如何规划一周的健康菜单。', 'nutrition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('protein-1', 'protein', 'Beans are a cheap source of protein for people who don''t eat meat.', '对不吃肉的人来说,豆类是便宜的蛋白质来源。', 'protein');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carbohydrate-1', 'carbohydrate', 'Athletes often eat more carbohydrates before a long race.', '运动员在长距离比赛前通常会多吃碳水化合物。', 'carbohydrates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vitamin-1', 'vitamin', 'Oranges and other fresh fruit contain plenty of vitamin C.', '橙子和其他新鲜水果含有丰富的维生素 C。', 'vitamin');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('calorie-1', 'calorie', 'This salad has fewer calories than most of the other lunches on the menu.', '这份沙拉的卡路里比菜单上大多数午餐都低。', 'calories');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fibre-1', 'fibre', 'Brown bread contains more fibre than white bread and keeps you full longer.', '全麦面包比白面包含有更多纤维,更耐饿。', 'fibre');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('organic-1', 'organic', 'The shop sells organic vegetables grown without any chemicals.', '这家店出售不使用任何化学品种植的有机蔬菜。', 'organic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tip-1', 'tip', 'Service isn''t included, so people usually leave a tip of ten percent.', '服务费不含在内,所以人们通常留百分之十的小费。', 'tip');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tip-2', 'tip', 'The guide gave us some useful tips on where to eat cheaply.', '导游告诉了我们一些去哪儿吃得便宜的实用建议。', 'tips');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('receipt-1', 'receipt', 'Keep your receipt in case you need to return the shoes.', '保留好收据,以防你需要退鞋。', 'receipt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discount-1', 'discount', 'Students can get a ten percent discount if they show their cards.', '学生出示证件可以享受九折优惠。', 'discount');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('voucher-1', 'voucher', 'This voucher gives you £5 off your next meal at the restaurant.', '这张代金券可以让你下次在这家餐厅用餐时减 5 英镑。', 'voucher');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bargain-1', 'bargain', 'This coat was a real bargain at half the original price.', '这件大衣打对折,真是捡了个便宜。', 'bargain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bargain-2', 'bargain', 'Tourists in the market often bargain with the sellers over prices.', '市场里的游客经常和小贩讨价还价。', 'bargain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('purchase-1', 'purchase', 'You can return any purchase within thirty days if you have the receipt.', '凭收据,任何购买的商品三十天内都可以退货。', 'purchase');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('purchase-2', 'purchase', 'Customers can purchase tickets online or at the door on the night.', '顾客可以在网上购票,也可以当晚在门口购买。', 'purchase');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cashier-1', 'cashier', 'Please pay the cashier at the front of the shop before you leave.', '离开前请到店铺前方的收银员处付款。', 'cashier');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('checkout-1', 'checkout', 'There was a long queue at the checkout, so I used the machines instead.', '收银台排着长队,所以我改用了自助机。', 'checkout');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('in-stock-1', 'in-stock', 'Is this jacket still in stock in a larger size?', '这件夹克还有大一点的尺码吗?', 'in stock');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('out-of-stock-1', 'out-of-stock', 'I''m afraid that model is out of stock until next month.', '恐怕那个型号要到下个月才有货。', 'out of stock');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('warranty-1', 'warranty', 'The washing machine comes with a two-year warranty on all parts.', '这台洗衣机所有零件都有两年保修。', 'warranty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('guarantee-1', 'guarantee', 'The camera has a one-year guarantee, so keep your receipt safe.', '这台相机保修一年,所以请保存好收据。', 'guarantee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('guarantee-2', 'guarantee', 'We guarantee delivery within three days or we''ll give your money back.', '我们保证三天内送达,否则退款。', 'guarantee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('delivery-1', 'delivery', 'Delivery is free on all orders over fifty pounds.', '订单满五十英镑一律免运费。', 'Delivery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('retailer-1', 'retailer', 'Most large retailers now allow customers to order online and collect in store.', '现在大多数大型零售商都允许顾客网上下单、到店取货。', 'retailers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wholesale-1', 'wholesale', 'The shop buys its goods at wholesale and sells them at a higher price.', '这家店以批发价进货,然后以更高的价格出售。', 'wholesale');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('merchandise-1', 'merchandise', 'The band sells T-shirts and other merchandise at the back of the hall.', '乐队在大厅后面出售 T 恤和其他商品。', 'merchandise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('second-hand-1', 'second-hand', 'I bought a second-hand bike from a student who was leaving.', '我从一个要离校的学生那里买了一辆二手自行车。', 'second-hand');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('department-store-1', 'department-store', 'The department store has clothes on the first floor and furniture on the top.', '百货商店二楼卖衣服,顶楼卖家具。', 'department store');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shopping-mall-1', 'shopping-mall', 'The new shopping mall has over a hundred shops and a cinema.', '新购物中心有一百多家商店和一家电影院。', 'shopping mall');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stall-1', 'stall', 'We bought some fresh cheese from a stall at the Saturday market.', '我们在周六集市的一个货摊上买了些新鲜奶酪。', 'stall');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cutlery-1', 'cutlery', 'The cutlery and plates are on the table by the door.', '刀叉和盘子在门边的桌子上。', 'cutlery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seasoning-1', 'seasoning', 'The dish needs a little more seasoning, perhaps some salt and pepper.', '这道菜需要再加点调味料,比如一些盐和胡椒。', 'seasoning');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vinegar-1', 'vinegar', 'Add a spoonful of vinegar to the sauce to give it a sharper taste.', '往酱汁里加一勺醋,味道会更酸爽。', 'vinegar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wholegrain-1', 'wholegrain', 'Wholegrain bread and rice are better for you than the white kinds.', '全谷物面包和糙米比白面包、白米更健康。', 'Wholegrain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dietitian-1', 'dietitian', 'My doctor sent me to a dietitian for advice on losing weight.', '医生让我去找营养师咨询减肥的建议。', 'dietitian');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gourmet-1', 'gourmet', 'The food was so good that even a gourmet would have enjoyed it.', '菜做得太好了,连美食家也会喜欢。', 'gourmet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gourmet-2', 'gourmet', 'The village market sells gourmet cheeses from small farms in the area.', '村里的集市出售来自当地小农场的美食级奶酪。', 'gourmet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bakery-1', 'bakery', 'The bakery on the corner sells fresh bread from seven every morning.', '街角的面包店每天早上七点开始卖新鲜面包。', 'bakery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('confectionery-1', 'confectionery', 'The shop sells chocolates, sweets and other confectionery made by hand.', '这家店出售手工制作的巧克力、糖果和其他糖果糕点。', 'confectionery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('boutique-1', 'boutique', 'She works in a small boutique selling designer dresses and handbags.', '她在一家卖名牌连衣裙和手提包的小精品店工作。', 'boutique');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('snack-1', 'snack', 'You can buy a snack from the machine next to the lecture hall.', '你可以在报告厅旁边的售货机上买零食。', 'snack');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cocktail-1', 'cocktail', 'The hotel bar serves a free cocktail to guests on their first night.', '酒店酒吧在客人入住第一晚免费赠送一杯鸡尾酒。', 'cocktail');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('barbecue-1', 'barbecue', 'If the weather stays fine, we''ll have a barbecue in the garden on Sunday.', '如果天气一直这么好,我们周日就在花园里烧烤。', 'barbecue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brunch-1', 'brunch', 'We usually meet for brunch on Sundays at about eleven o''clock.', '我们通常周日十一点左右见面吃早午餐。', 'brunch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('greasy-1', 'greasy', 'The chips were so greasy that I couldn''t finish them.', '薯条太油腻了,我没吃完。', 'greasy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('savoury-1', 'savoury', 'Would you prefer something savoury, like cheese, or something sweet?', '您想吃点咸的,比如奶酪,还是甜的?', 'savoury');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fragrant-1', 'fragrant', 'The kitchen was fragrant with the smell of fresh herbs and garlic.', '厨房里飘着新鲜香草和大蒜的香味。', 'fragrant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nourish-1', 'nourish', 'Good soup can nourish you when you''re getting over a cold.', '感冒快好时,喝点好汤能补充营养。', 'nourish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('convenience-store-1', 'convenience-store', 'There''s a convenience store near the flat that stays open until midnight.', '公寓附近有一家开到午夜的便利店。', 'convenience store');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fitting-room-1', 'fitting-room', 'The fitting room is at the back, if you''d like to try it on.', '如果想试穿,试衣间在后面。', 'fitting room');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shopping-spree-1', 'shopping-spree', 'I went on a shopping spree after getting my first month''s pay.', '拿到第一个月工资后,我去疯狂购物了一番。', 'shopping spree');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('staple-food-1', 'staple-food', 'Rice is the staple food for many families in this part of Asia.', '在亚洲这一地区,大米是许多家庭的主食。', 'staple food');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mall-1', 'mall', 'We spent the afternoon at the mall looking for a birthday present.', '我们下午在购物中心找生日礼物。', 'mall');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outlet-1', 'outlet', 'The factory outlet on Mill Road sells last year''s coats at half price.', '磨坊路上的工厂直销店半价出售去年款的大衣。', 'outlet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outlet-2', 'outlet', 'There is a power outlet under each desk in the study room.', '自习室每张书桌下面都有一个电源插座。', 'outlet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('parcel-1', 'parcel', 'A parcel came for you this morning, so I left it in your room.', '今天早上有你的包裹,我放在你房间了。', 'parcel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('swap-1', 'swap', 'Could I swap this shirt for a smaller one, please?', '我可以把这件衬衫换成小一号的吗?', 'swap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dining-1', 'dining', 'The hotel''s dining room is open from seven until ten every evening.', '酒店餐厅每晚七点到十点营业。', 'dining');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('feast-1', 'feast', 'The village holds a great feast with music at the end of harvest.', '收获季结束时,村里会举办盛宴,还有音乐表演。', 'feast');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coupon-1', 'coupon', 'Use this coupon to get free coffee with any sandwich.', '用这张优惠券,买任意三明治都送一杯免费咖啡。', 'coupon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fry-1', 'fry', 'Fry the onions gently in butter until they turn soft and golden.', '用黄油小火煎洋葱,直到变软变金黄。', 'Fry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('roast-1', 'roast', 'Roast the chicken for about an hour until the skin is crisp.', '把鸡烤一小时左右,直到外皮酥脆。', 'Roast');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('roast-2', 'roast', 'We usually have roast beef with vegetables for Sunday lunch.', '我们周日午餐通常吃烤牛肉配蔬菜。', 'roast');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slice-1', 'slice', 'Would you like another slice of cake before you go?', '你走之前要再来一片蛋糕吗?', 'slice');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slice-2', 'slice', 'Slice the tomatoes thinly and put them on top of the cheese.', '把番茄切成薄片,放在奶酪上面。', 'Slice');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('loaf-1', 'loaf', 'Could you pick up a loaf of bread on your way home?', '你回家路上能买一条面包吗?', 'loaf');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('appetite-1', 'appetite', 'I had no appetite for days after I got back from the trip.', '旅行回来后,我好几天都没有食欲。', 'appetite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flavour-1', 'flavour', 'Fresh herbs add a lot of flavour to a simple tomato sauce.', '新鲜香草能让简单的番茄酱风味大增。', 'flavour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('account-1', 'account', 'I''d like to open an account for my wages, please.', '我想开一个账户用来收工资。', 'account');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('current-account-1', 'current-account', 'A current account lets you pay bills and take out money at any time.', '活期账户可以让你随时支付账单和取钱。', 'current account');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('savings-account-1', 'savings-account', 'I put a little money into my savings account every month.', '我每个月往储蓄账户里存一点钱。', 'savings account');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('joint-account-1', 'joint-account', 'My partner and I opened a joint account to pay the rent and bills.', '我和伴侣开了一个联名账户,用来付房租和账单。', 'joint account');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deposit-1', 'deposit', 'You need to pay a deposit of £50 to hold the room.', '你需要付 50 英镑定金来保留这个房间。', 'deposit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deposit-2', 'deposit', 'You can deposit cash at the machines inside the bank until eight.', '你可以在八点前用银行内的机器存入现金。', 'deposit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('withdraw-1', 'withdraw', 'You can withdraw up to £300 a day from any cash machine.', '你每天可以从任何一台取款机取款,最多 300 英镑。', 'withdraw');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('withdrawal-1', 'withdrawal', 'There''s no charge for a withdrawal from machines at our own branches.', '在我们自己网点的机器上取款不收费。', 'withdrawal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('balance-1', 'balance', 'You can check your account balance at any cash machine.', '你可以在任何一台取款机上查询账户余额。', 'balance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('balance-2', 'balance', 'It''s hard to find a balance between part-time work and my studies.', '很难在兼职和学习之间找到平衡。', 'balance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('balance-3', 'balance', 'Students must learn to balance their spending against their income each month.', '学生必须学会每月平衡自己的支出和收入。', 'balance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('statement-1', 'statement', 'Your monthly statement shows every payment you''ve made from the account.', '你的月度对账单显示了从账户支出的每一笔款项。', 'statement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('statement-2', 'statement', 'The bank issued a statement apologising for the problems with its website.', '这家银行发表声明,就网站出现的问题道歉。', 'statement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interest-rate-1', 'interest-rate', 'The bank offers a low interest rate on loans for students.', '银行为学生贷款提供较低的利率。', 'interest rate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overdraft-1', 'overdraft', 'The bank charges a small fee if you go over your overdraft limit.', '如果超出透支额度,银行会收取一小笔费用。', 'overdraft');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('loan-1', 'loan', 'I took out a loan to pay for my car.', '我贷了一笔款来买车。', 'loan');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mortgage-1', 'mortgage', 'They had to take out a large mortgage to buy their first home.', '他们不得不申请一大笔按揭贷款来买第一套房。', 'mortgage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('credit-card-1', 'credit-card', 'You can pay by credit card or in cash at the front desk.', '你可以在前台用信用卡或现金付款。', 'credit card');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('debit-card-1', 'debit-card', 'A debit card takes the money directly from your bank account.', '借记卡会直接从你的银行账户扣款。', 'debit card');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cheque-1', 'cheque', 'We no longer accept payment by cheque, only by card or cash.', '我们不再接受支票付款,只收银行卡或现金。', 'cheque');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('instalment-1', 'instalment', 'You can pay for the course in three monthly instalments.', '你可以分三个月分期支付课程费用。', 'instalments');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fee-1', 'fee', 'The bank charges a monthly fee of £5 for this account.', '这个账户银行每月收取 5 英镑费用。', 'fee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('charge-1', 'charge', 'There''s a small charge for using the swimming pool at weekends.', '周末使用游泳池要收取少量费用。', 'charge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('charge-2', 'charge', 'The hotel will charge you for any drinks taken from the fridge.', '冰箱里的饮料一经取用,酒店将向你收费。', 'charge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('charge-3', 'charge', 'Police decided to charge the driver with careless driving after the accident.', '事故发生后,警方决定以驾驶疏忽罪控告这名司机。', 'charge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('identification-1', 'identification', 'You''ll need some form of identification to open an account here.', '在这里开户需要提供某种身份证明。', 'identification');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('proof-of-address-1', 'proof-of-address', 'A recent gas bill can be used as proof of address.', '最近的煤气费账单可以用作地址证明。', 'proof of address');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('signature-1', 'signature', 'We need your signature at the bottom of the second page.', '我们需要你在第二页底部签名。', 'signature');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pin-1', 'pin', 'Never tell anyone your PIN, even if they say they work for the bank.', '绝不要把银行卡密码告诉任何人,即使对方自称是银行员工。', 'PIN');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('online-banking-1', 'online-banking', 'With online banking, you can pay your bills from your phone at any time.', '有了网上银行,你可以随时用手机支付账单。', 'online banking');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('branch-1', 'branch', 'Our nearest branch is on the High Street, next to the post office.', '我们最近的分行在高街,紧邻邮局。', 'branch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('branch-2', 'branch', 'A large branch fell from the tree and damaged the roof of the shed.', '一根大树枝从树上掉下来,砸坏了棚屋的屋顶。', 'branch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cashpoint-1', 'cashpoint', 'Is there a cashpoint near here where I can get some money?', '这附近有可以取钱的自动取款机吗?', 'cashpoint');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('budget-1', 'budget', 'We have a budget of about £800 for the whole holiday.', '我们整个假期的预算大约是 800 英镑。', 'budget');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('expenditure-1', 'expenditure', 'Students should keep a record of their weekly income and expenditure.', '学生应该记录每周的收入和开支。', 'expenditure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tuition-fee-1', 'tuition-fee', 'The tuition fee for this course is higher for overseas students.', '这门课程对海外学生收取的学费更高。', 'tuition fee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scholarship-1', 'scholarship', 'She won a scholarship that covers all her costs for three years.', '她获得了一笔奖学金,可以支付三年的全部费用。', 'scholarship');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grant-1', 'grant', 'Some students can apply for a government grant to help with living costs.', '部分学生可以申请政府补助金来支付生活费。', 'grant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grant-2', 'grant', 'The college may grant you extra time if you are ill.', '如果你生病了,学院可能会给你额外的时间。', 'grant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('allowance-1', 'allowance', 'My parents give me a small monthly allowance while I''m at university.', '我上大学期间,父母每月给我一小笔零用钱。', 'allowance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('teller-1', 'teller', 'The teller asked to see my passport before giving me the money.', '银行出纳员要求先看我的护照才把钱给我。', 'teller');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('denomination-1', 'denomination', 'The machine only gives out notes in a denomination of twenty pounds.', '这台机器只吐面额二十英镑的钞票。', 'denomination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('documentation-1', 'documentation', 'You must bring the correct documentation when you apply for a bank account.', '申请银行账户时必须带齐相关证明文件。', 'documentation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transaction-1', 'transaction', 'Every transaction you make will appear on your monthly statement.', '你的每笔交易都会显示在月度对账单上。', 'transaction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('savings-1', 'savings', 'I used all my savings to pay for the trip to Canada.', '我把所有积蓄都用来支付去加拿大的旅行了。', 'savings');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('premium-1', 'premium', 'The insurance premium goes up each year as you get older.', '保险费会随着年龄增长逐年上涨。', 'premium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('premium-2', 'premium', 'Premium seats cost more, but they have a much better view of the stage.', '优质座位更贵,但看舞台的视野好得多。', 'Premium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('remuneration-1', 'remuneration', 'Remuneration for the job includes a basic salary plus a company car.', '这份工作的报酬包括基本工资和一辆公司配车。', 'Remuneration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reimburse-1', 'reimburse', 'The company will reimburse your travel costs if you keep the tickets.', '只要保留车票,公司就会报销你的差旅费。', 'reimburse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rebate-1', 'rebate', 'You may be able to claim a tax rebate if you''ve paid too much.', '如果多缴了税,你也许可以申请部分退款。', 'rebate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('collateral-1', 'collateral', 'The bank asked him to use his house as collateral for the loan.', '银行要求他用房子作为这笔贷款的抵押品。', 'collateral');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('audit-1', 'audit', 'An outside company carries out an audit of the club''s accounts every year.', '每年都由外部公司对俱乐部的账目进行审计。', 'audit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bank-statement-1', 'bank-statement', 'You''ll need to show a recent bank statement to rent the flat.', '租这套公寓需要出示最近的银行对账单。', 'bank statement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('credit-limit-1', 'credit-limit', 'My credit limit is £1,000, so I can''t pay for the whole trip.', '我的信用额度是 1000 英镑,所以付不起全部旅费。', 'credit limit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('handling-fee-1', 'handling-fee', 'A small handling fee is added when you buy tickets over the phone.', '电话购票要加收一小笔手续费。', 'handling fee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('down-payment-1', 'down-payment', 'We saved for five years to make a down payment on the house.', '我们攒了五年钱,才付得起这套房子的首付。', 'down payment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('identity-card-1', 'identity-card', 'Please show your identity card at the door when you arrive.', '到达时请在门口出示你的身份证。', 'identity card');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pay-slip-1', 'pay-slip', 'Your pay slip shows how much tax you''ve paid this month.', '你的工资单显示了你这个月缴了多少税。', 'pay slip');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('payable-1', 'payable', 'The full amount is payable when you collect the car.', '全部款项在提车时支付。', 'payable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sterling-1', 'sterling', 'The hotel only accepts payment in sterling, not in euros.', '这家酒店只接受英镑付款,不收欧元。', 'sterling');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invoice-1', 'invoice', 'We''ll send you an invoice when the work has been finished.', '工作完成后,我们会把发票寄给你。', 'invoice');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lender-1', 'lender', 'Most lenders will want to see proof of your income first.', '大多数贷款方都会先要求查看你的收入证明。', 'lenders');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lottery-1', 'lottery', 'He spent the money he won on the lottery on a new house.', '他用彩票中奖的钱买了一栋新房子。', 'lottery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bid-1', 'bid', 'Someone made a bid of £200 for the old painting at the sale.', '拍卖会上有人出价 200 英镑买这幅旧画。', 'bid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bid-2', 'bid', 'Three local companies will bid for the contract to build the new library.', '当地三家公司将投标建造新图书馆的合同。', 'bid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('appointment-1', 'appointment', 'I''d like to make an appointment with the doctor for Thursday morning.', '我想预约周四上午看医生。', 'appointment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clinic-1', 'clinic', 'The clinic is open from eight until six on weekdays.', '这家诊所工作日从八点开到六点。', 'clinic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('surgery-1', 'surgery', 'The doctor''s surgery is closed on Saturday afternoons and all day Sunday.', '这家诊所周六下午和周日全天不开门。', 'surgery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('surgery-2', 'surgery', 'My father needed surgery on his knee after the accident.', '事故后,我父亲的膝盖需要动手术。', 'surgery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gp-1', 'gp', 'You should register with a local GP as soon as you arrive.', '你一到就应该去当地的全科医生那里登记。', 'GP');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('physician-1', 'physician', 'The physician asked about my diet and sent me for a blood test.', '内科医生询问了我的饮食,并让我去验血。', 'physician');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('surgeon-1', 'surgeon', 'The surgeon explained how long the operation on my shoulder would take.', '外科医生解释了我的肩部手术需要多长时间。', 'surgeon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pharmacist-1', 'pharmacist', 'Ask the pharmacist if you aren''t sure how to take this medicine.', '如果不确定这种药怎么吃,就问问药剂师。', 'pharmacist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pharmacy-1', 'pharmacy', 'The pharmacy next to the station stays open until ten at night.', '车站旁边的药房营业到晚上十点。', 'pharmacy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prescription-1', 'prescription', 'You can''t buy this medicine without a prescription from your doctor.', '没有医生的处方,你买不到这种药。', 'prescription');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('symptom-1', 'symptom', 'Common symptoms of the flu include a high temperature and sore muscles.', '流感的常见症状包括高烧和肌肉酸痛。', 'symptoms');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diagnosis-1', 'diagnosis', 'The doctor can''t give a diagnosis until the test results come back.', '检查结果出来之前,医生无法作出诊断。', 'diagnosis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('treatment-1', 'treatment', 'Treatment at this hospital is free for all full-time students.', '所有全日制学生在这家医院都可以免费治疗。', 'Treatment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('therapy-1', 'therapy', 'She had speech therapy for six months after the operation.', '手术后她接受了六个月的语言治疗。', 'therapy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('physiotherapy-1', 'physiotherapy', 'You''ll need physiotherapy twice a week until your knee gets stronger.', '在膝盖恢复力量之前,你每周需要做两次理疗。', 'physiotherapy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('injury-1', 'injury', 'He missed the whole season because of a serious knee injury.', '他因膝盖重伤错过了整个赛季。', 'injury');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sprain-1', 'sprain', 'It''s only a sprain, but you should rest your ankle for a week.', '只是扭伤,但你的脚踝应该休息一周。', 'sprain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sprain-2', 'sprain', 'Be careful not to sprain your wrist when you lift heavy boxes.', '搬重箱子时小心别扭伤手腕。', 'sprain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fracture-1', 'fracture', 'The X-ray showed a small fracture in the bone of my left arm.', 'X 光显示我的左臂骨头有轻微骨折。', 'fracture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bruise-1', 'bruise', 'I fell off my bike and got a big bruise on my leg.', '我从自行车上摔下来,腿上青了一大块。', 'bruise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('infection-1', 'infection', 'Keep the cut clean, or it could easily lead to an infection.', '保持伤口清洁,否则很容易引起感染。', 'infection');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fever-1', 'fever', 'She stayed home from school because she had a high fever.', '她发高烧,所以没去上学。', 'fever');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('headache-1', 'headache', 'I''ve had a terrible headache since I got up this morning.', '我今早起床后头就疼得厉害。', 'headache');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('insomnia-1', 'insomnia', 'Too much coffee late in the day can cause insomnia.', '下午晚些时候喝太多咖啡可能导致失眠。', 'insomnia');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('check-up-1', 'check-up', 'It''s a good idea to have a dental check-up every six months.', '最好每六个月做一次牙科检查。', 'check-up');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vaccination-1', 'vaccination', 'You should get a vaccination at least a month before you travel.', '你应该至少在出行前一个月接种疫苗。', 'vaccination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('emergency-1', 'emergency', 'In an emergency, call this number and ask for an ambulance.', '遇到紧急情况,请拨打这个号码叫救护车。', 'emergency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ambulance-1', 'ambulance', 'An ambulance arrived within minutes and took him to hospital.', '救护车几分钟内就到了,把他送进了医院。', 'ambulance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('casualty-1', 'casualty', 'They took her straight to casualty because the cut was so deep.', '伤口太深,他们直接把她送到了急诊室。', 'casualty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('medical-record-1', 'medical-record', 'The new doctor will need to see your medical records from home.', '新医生需要查看你在家乡的病历。', 'medical records');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dentist-1', 'dentist', 'I''m going to the dentist tomorrow because one of my teeth hurts.', '我明天要去看牙医,因为有颗牙疼。', 'dentist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('optician-1', 'optician', 'The optician said I needed stronger glasses for reading.', '验光师说我需要度数更高的阅读眼镜。', 'optician');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fitness-1', 'fitness', 'The new fitness class starts at six and lasts about forty minutes.', '新的健身课六点开始,大约持续四十分钟。', 'fitness');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gym-membership-1', 'gym-membership', 'A gym membership costs £30 a month, but students pay less.', '健身房会员每月 30 英镑,但学生更便宜。', 'gym membership');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stamina-1', 'stamina', 'Running twice a week has really improved my stamina.', '每周跑两次步确实提高了我的耐力。', 'stamina');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stretch-1', 'stretch', 'Remember to stretch your legs before you start running.', '开始跑步前记得伸展腿部。', 'stretch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('posture-1', 'posture', 'Sitting at a computer all day can give you bad posture.', '整天坐在电脑前会让你姿势不良。', 'posture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diagnose-1', 'diagnose', 'It took doctors several weeks to diagnose the cause of the pain.', '医生花了好几周才诊断出疼痛的原因。', 'diagnose');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('remedy-1', 'remedy', 'Honey and lemon are a popular home remedy for a sore throat.', '蜂蜜加柠檬是治疗喉咙痛的常见家庭疗法。', 'remedy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('remedy-2', 'remedy', 'The hotel manager promised to remedy the problem with the hot water.', '酒店经理承诺解决热水的问题。', 'remedy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bandage-1', 'bandage', 'The nurse cleaned the cut and put a bandage around my hand.', '护士清理了伤口,在我手上缠了绷带。', 'bandage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thermometer-1', 'thermometer', 'Use the thermometer in the first aid box to check her temperature.', '用急救箱里的温度计给她量体温。', 'thermometer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ointment-1', 'ointment', 'Put this ointment on the burn twice a day until it heals.', '每天在烧伤处涂两次这种药膏,直到痊愈。', 'ointment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('syrup-1', 'syrup', 'Children under six should take the cough syrup instead of tablets.', '六岁以下的儿童应该服用止咳糖浆,而不是药片。', 'syrup');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bleed-1', 'bleed', 'Press firmly on the cut if it starts to bleed again.', '如果伤口再次流血,就用力按住。', 'bleed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('numb-1', 'numb', 'My fingers went numb after an hour in the freezing water.', '在冰水里泡了一小时后,我的手指都麻木了。', 'numb');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('feverish-1', 'feverish', 'I felt feverish all night, so I called in sick this morning.', '我整晚都觉得发烧,所以今早打电话请了病假。', 'feverish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relapse-1', 'relapse', 'Rest for another week, or you might have a relapse.', '再休息一周,否则你可能会复发。', 'relapse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recuperate-1', 'recuperate', 'He went to stay with his parents to recuperate after the operation.', '手术后他去父母家住了一段时间休养。', 'recuperate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pulse-1', 'pulse', 'The nurse took my pulse and told me to sit down for a while.', '护士给我量了脉搏,让我坐下休息一会儿。', 'pulse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fatigue-1', 'fatigue', 'Long hours and poor sleep can cause fatigue and headaches.', '长时间工作和睡眠不足可能导致疲劳和头痛。', 'fatigue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sneeze-1', 'sneeze', 'I can''t stop sneezing whenever there''s a cat in the room.', '只要房间里有猫,我就打喷嚏打个不停。', 'sneezing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pregnant-1', 'pregnant', 'Pregnant women shouldn''t take this medicine without asking a doctor.', '孕妇未经医生同意不应服用这种药。', 'Pregnant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sickness-1', 'sickness', 'Take one of these tablets before the boat trip to avoid sickness.', '坐船前吃一片这种药,可以防止恶心。', 'sickness');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('throat-1', 'throat', 'I''ve had a sore throat and a cough for about three days.', '我喉咙痛、咳嗽已经大约三天了。', 'throat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ankle-1', 'ankle', 'I twisted my ankle on the stairs and can''t walk very far.', '我在楼梯上扭了脚踝,走不了太远。', 'ankle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sore-1', 'sore', 'My legs were sore for two days after the long walk.', '长途步行后,我的腿酸痛了两天。', 'sore');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tablet-1', 'tablet', 'Take two tablets with water after every meal.', '每餐后用水送服两片药。', 'tablets');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tablet-2', 'tablet', 'I read most of my course books on a tablet these days.', '现在我的课本大多在平板电脑上看。', 'tablet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('capsule-1', 'capsule', 'Swallow the capsule whole with a glass of water, and don''t chew it.', '用一杯水整粒吞下胶囊,不要嚼。', 'capsule');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nap-1', 'nap', 'I usually have a short nap after lunch on Sundays.', '周日午饭后我通常小睡一会儿。', 'nap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('club-1', 'club', 'I joined a badminton club when I started at university.', '我上大学时加入了一个羽毛球俱乐部。', 'club');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('membership-1', 'membership', 'Your membership includes free use of the pool and the tennis courts.', '你的会员资格包括免费使用游泳池和网球场。', 'membership');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('membership-fee-1', 'membership-fee', 'The annual membership fee is £40, or £25 for students.', '年度会费是 40 英镑,学生 25 英镑。', 'membership fee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('registration-fee-1', 'registration-fee', 'There''s a one-off registration fee of £10 when you join the course.', '报名这门课程时要一次性交 10 英镑报名费。', 'registration fee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('venue-1', 'venue', 'The venue for this year''s concert is the town hall, not the park.', '今年音乐会的场地是市政厅,不是公园。', 'venue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('event-1', 'event', 'The next event in the programme is a talk on local history.', '节目单上的下一项活动是一场关于当地历史的讲座。', 'event');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exhibition-1', 'exhibition', 'The photography exhibition is free and runs until the end of March.', '这场摄影展免费参观,展期到三月底。', 'exhibition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('festival-1', 'festival', 'The town''s music festival takes place every year in early July.', '小镇的音乐节每年七月初举行。', 'festival');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carnival-1', 'carnival', 'Thousands of people dance through the streets during the summer carnival.', '夏季狂欢节期间,成千上万的人在街上跳舞。', 'carnival');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('parade-1', 'parade', 'The parade will start at the bridge and finish in the main square.', '游行将从桥边开始,到中心广场结束。', 'parade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('concert-1', 'concert', 'There''s a free concert in the park on Saturday evening.', '周六晚上公园里有一场免费音乐会。', 'concert');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('performance-1', 'performance', 'Tonight''s performance begins at half past seven and ends at ten.', '今晚的演出七点半开始,十点结束。', 'performance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('audience-1', 'audience', 'The audience stood and clapped for several minutes after the show.', '演出结束后,观众起立鼓掌了好几分钟。', 'audience');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spectator-1', 'spectator', 'Over two thousand spectators watched the final match of the tournament.', '两千多名观众观看了锦标赛的决赛。', 'spectators');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('admission-1', 'admission', 'Admission to the museum is free for children under twelve.', '十二岁以下儿童免费进入博物馆。', 'Admission');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ticket-office-1', 'ticket-office', 'You can collect your tickets from the ticket office before the show.', '你可以在演出前到售票处取票。', 'ticket office');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('box-office-1', 'box-office', 'Call the box office to check whether any seats are left.', '打电话给售票处,看看还有没有座位。', 'box office');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('programme-1', 'programme', 'The evening''s programme is printed on the back of your ticket.', '当晚的节目单印在你的门票背面。', 'programme');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('schedule-1', 'schedule', 'Please look at the schedule to see when each talk begins.', '请查看日程,了解每场讲座的开始时间。', 'schedule');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('schedule-2', 'schedule', 'We''ve scheduled the meeting for nine, but it may start a little later.', '我们把会议安排在九点,但可能会稍晚开始。', 'scheduled');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rehearsal-1', 'rehearsal', 'The final rehearsal is on Friday, and everyone needs to be there.', '最后一次排练在周五,大家都必须到场。', 'rehearsal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('organiser-1', 'organiser', 'The organisers have moved the race to Sunday because of the weather.', '由于天气原因,组织者把比赛改到了周日。', 'organisers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sponsor-1', 'sponsor', 'A local bank is the main sponsor of this year''s marathon.', '当地一家银行是今年马拉松的主要赞助商。', 'sponsor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sponsor-2', 'sponsor', 'Several shops have agreed to sponsor the school''s summer sports day.', '几家商店同意赞助学校的夏季运动会。', 'sponsor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('charity-1', 'charity', 'All the money from the book sale will go to a children''s charity.', '图书义卖的所有收入都将捐给一家儿童慈善机构。', 'charity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fundraising-1', 'fundraising', 'We''re holding a fundraising dinner to pay for the new playground.', '我们将举办一场筹款晚宴,为新游乐场筹集资金。', 'fundraising');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('raffle-1', 'raffle', 'You can win a free holiday in the raffle at tonight''s dinner.', '在今晚晚宴的抽奖中,你有机会赢得一次免费度假。', 'raffle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('competition-1', 'competition', 'Students can enter the photography competition by sending in three pictures.', '学生提交三张照片即可参加摄影比赛。', 'competition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tournament-1', 'tournament', 'Our team reached the semi-final of the tennis tournament last year.', '我们队去年打进了网球锦标赛的半决赛。', 'tournament');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('league-1', 'league', 'Our college team finished second in the league last season.', '我们学院的球队上赛季在联赛中获得第二名。', 'league');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('instructor-1', 'instructor', 'The instructor will show you how to use the machines safely.', '教练会教你如何安全使用这些器械。', 'instructor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('beginner-1', 'beginner', 'This class is for complete beginners, so you don''t need any experience.', '这门课面向零基础的初学者,所以你不需要任何经验。', 'beginners');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intermediate-1', 'intermediate', 'I''ve moved up to the intermediate group now that I can swim well.', '我现在游得不错,已经升到中级组了。', 'intermediate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('advanced-1', 'advanced', 'The advanced course is only for people who''ve been climbing for years.', '高级课程只面向有多年攀岩经验的人。', 'advanced');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('equipment-1', 'equipment', 'All the equipment is provided, but you should bring your own towel.', '所有装备都有提供,但你要自带毛巾。', 'equipment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('kit-1', 'kit', 'Please remember to bring your football kit to the training session.', '请记得带上你的足球装备来参加训练。', 'kit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('locker-1', 'locker', 'You''ll need a pound coin to use the lockers by the pool.', '使用泳池边的储物柜需要一枚一英镑硬币。', 'lockers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('changing-room-1', 'changing-room', 'Please leave your wet shoes outside the changing room.', '请把湿鞋子放在更衣室外面。', 'changing room');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('swimming-pool-1', 'swimming-pool', 'The swimming pool will be closed for cleaning all next week.', '游泳池下周全周关闭清洁。', 'swimming pool');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sports-centre-1', 'sports-centre', 'The only free slot at the sports centre is at ten on Thursday.', '体育中心唯一空着的时段是周四十点。', 'sports centre');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('leisure-centre-1', 'leisure-centre', 'The leisure centre offers swimming lessons for adults on Monday evenings.', '休闲中心周一晚上有成人游泳课。', 'leisure centre');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hiking-1', 'hiking', 'Bring strong boots and warm clothes if you''re going hiking in the mountains.', '如果去山里徒步,请带上结实的靴子和保暖衣物。', 'hiking');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cycling-1', 'cycling', 'Cycling is the cheapest and easiest way to get around the city.', '骑行是在城里出行最便宜、最方便的方式。', 'Cycling');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('canoeing-1', 'canoeing', 'We went canoeing on the river and saw lots of birds along the way.', '我们在河上划独木舟,一路上看到很多鸟。', 'canoeing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sailing-1', 'sailing', 'The club offers sailing lessons at the lake during the summer.', '俱乐部夏天在湖上开设帆船课程。', 'sailing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('snorkelling-1', 'snorkelling', 'The water around the island is clear, so it''s ideal for snorkelling.', '岛周围的海水清澈,非常适合浮潜。', 'snorkelling');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('yoga-1', 'yoga', 'I go to a yoga class twice a week to help me relax.', '我每周上两次瑜伽课来帮助放松。', 'yoga');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pottery-1', 'pottery', 'In the pottery class, you''ll learn to make your own bowls and cups.', '在陶艺课上,你将学习制作自己的碗和杯子。', 'pottery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('photography-1', 'photography', 'The photography club meets on Thursdays and often goes out at weekends.', '摄影俱乐部每周四聚会,周末也常外出拍摄。', 'photography');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gardening-1', 'gardening', 'My neighbour spends most of her free time gardening at the back of the house.', '我的邻居大部分空闲时间都在屋后做园艺。', 'gardening');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crafts-1', 'crafts', 'The market sells local crafts such as baskets and handmade jewellery.', '这个集市出售篮子和手工首饰等当地手工艺品。', 'crafts');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('refreshments-1', 'refreshments', 'Light refreshments will be served in the hall after the talk.', '讲座结束后,大厅将提供简单的茶点。', 'refreshments');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('raincoat-1', 'raincoat', 'Take a raincoat with you, because the forecast says it might rain.', '带上雨衣吧,天气预报说可能会下雨。', 'raincoat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('waterproof-1', 'waterproof', 'You''ll need a waterproof jacket for the boat trip this afternoon.', '今天下午的乘船游你需要一件防水夹克。', 'waterproof');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stadium-1', 'stadium', 'The new stadium holds forty thousand people and has a roof.', '新体育场能容纳四万人,还有屋顶。', 'stadium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('champion-1', 'champion', 'She became the national swimming champion when she was only sixteen.', '她年仅十六岁就成为全国游泳冠军。', 'champion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('medal-1', 'medal', 'Every child who finishes the race will receive a medal.', '每个跑完全程的孩子都会得到一枚奖牌。', 'medal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('participant-1', 'participant', 'All participants must fill in a form before the walk begins.', '所有参与者必须在徒步开始前填写表格。', 'participants');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('host-1', 'host', 'Our town will host the regional athletics competition next spring.', '明年春天,我们镇将主办地区田径比赛。', 'host');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('host-2', 'host', 'As the host of the party, he welcomed each guest at the door.', '作为派对的主人,他在门口迎接每位客人。', 'host');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('celebrate-1', 'celebrate', 'We''re having a meal on Friday to celebrate the end of exams.', '我们周五要聚餐,庆祝考试结束。', 'celebrate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('celebration-1', 'celebration', 'There''ll be a big celebration in the village for the school''s anniversary.', '村里将为学校周年举行盛大的庆典。', 'celebration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invitation-1', 'invitation', 'I received an invitation to the opening of the new art gallery.', '我收到了新美术馆开幕的邀请。', 'invitation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decoration-1', 'decoration', 'The children made all the decorations for the hall themselves.', '大厅里所有的装饰都是孩子们自己做的。', 'decorations');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('loudspeaker-1', 'loudspeaker', 'The results were announced over a loudspeaker at the end of the day.', '当天结束时,成绩通过扬声器宣布。', 'loudspeaker');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('microphone-1', 'microphone', 'Please speak into the microphone so everyone at the back can hear you.', '请对着麦克风讲话,让后面的人都能听到。', 'microphone');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('costume-1', 'costume', 'She made her own costume for the school play about the Romans.', '她为学校那部关于罗马人的戏剧亲手做了戏服。', 'costume');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('circus-1', 'circus', 'The circus comes to town every summer and stays for a week.', '马戏团每年夏天都来镇上,待一周。', 'circus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('backstage-1', 'backstage', 'After the show, we were invited backstage to meet the actors.', '演出结束后,我们受邀到后台与演员见面。', 'backstage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rehearse-1', 'rehearse', 'The band will rehearse in the main hall from four until six.', '乐队四点到六点在主厅排练。', 'rehearse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('perform-1', 'perform', 'The students will perform two short plays at the end of term.', '学生们将在期末表演两部短剧。', 'perform');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('perform-2', 'perform', 'Nurses perform many important tasks that doctors don''t have time for.', '护士执行许多医生无暇顾及的重要任务。', 'perform');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('puppetry-1', 'puppetry', 'Children can learn the art of puppetry at the Saturday workshop.', '孩子们可以在周六的工作坊学习木偶戏艺术。', 'puppetry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('juggle-1', 'juggle', 'The street performer can juggle five balls while riding a bicycle.', '这位街头艺人能一边骑自行车一边抛接五个球。', 'juggle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('juggle-2', 'juggle', 'I have to juggle my part-time job and my course work every week.', '我每周都要兼顾兼职和课程作业。', 'juggle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mime-1', 'mime', 'The actors told the whole story through mime, without saying a word.', '演员们用哑剧讲述了整个故事,一句话也没说。', 'mime');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gymnastics-1', 'gymnastics', 'She has been doing gymnastics since she was five years old.', '她从五岁起就开始练体操。', 'gymnastics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trekking-1', 'trekking', 'We went trekking in Nepal for two weeks with a small group.', '我们和一个小团队在尼泊尔长途徒步了两周。', 'trekking');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('surfing-1', 'surfing', 'The beach is popular for surfing because the waves are so big.', '这片海滩因海浪很大而成为冲浪胜地。', 'surfing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('skiing-1', 'skiing', 'We go skiing in Austria every winter with our cousins.', '我们每年冬天都和表亲去奥地利滑雪。', 'skiing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('skating-1', 'skating', 'The outdoor skating rink opens in December, when the weather gets colder.', '室外滑冰场十二月开放,那时天气更冷了。', 'skating');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('goalkeeper-1', 'goalkeeper', 'Our goalkeeper stopped the ball at the last minute and saved the game.', '我们的守门员在最后一分钟扑出了球,挽救了比赛。', 'goalkeeper');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('racket-1', 'racket', 'You can hire a tennis racket from the desk for two pounds.', '你可以花两英镑在服务台租一只网球拍。', 'racket');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spa-1', 'spa', 'The hotel has a spa with a sauna and a small indoor pool.', '酒店有一个水疗中心,设有桑拿房和小型室内泳池。', 'spa');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fancy-dress-1', 'fancy-dress', 'Everyone came in fancy dress for the party at the end of term.', '大家都穿着化装服来参加期末派对。', 'fancy dress');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('puppet-show-1', 'puppet-show', 'The children loved the puppet show at the library on Saturday.', '孩子们很喜欢周六在图书馆看的木偶戏表演。', 'puppet show');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slot-1', 'slot', 'We''ve got a free slot for a lesson at three on Wednesday.', '我们周三三点有一个空的上课时段。', 'slot');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slot-2', 'slot', 'Put a coin in the slot and the machine will give you a ticket.', '往投币口放一枚硬币,机器就会出票。', 'slot');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('novice-1', 'novice', 'Even a complete novice can learn to ride a horse in a few lessons.', '即使是完全的新手,上几节课也能学会骑马。', 'novice');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('entrant-1', 'entrant', 'Each entrant in the race will get a number to wear on their shirt.', '每位参赛者都会拿到一个号码,贴在衣服上。', 'entrant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('punch-1', 'punch', 'He was sent off for trying to punch another player during the game.', '他在比赛中试图拳击另一名球员,被罚下场。', 'punch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('punch-2', 'punch', 'The driver will punch your ticket when you get on the bus.', '上车时司机会给你的车票打孔。', 'punch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('opponent-1', 'opponent', 'My opponent in the final was much taller and had a stronger serve.', '我决赛的对手比我高得多,发球也更有力。', 'opponent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rival-1', 'rival', 'Our team plays its biggest rival from the next town on Saturday.', '周六,我们队将迎战邻镇最大的竞争对手。', 'rival');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rival-2', 'rival', 'Two rival companies are both trying to win the same contract.', '两家竞争公司都在争取同一份合同。', 'rival');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contest-1', 'contest', 'She won first prize in a poetry contest at her local library.', '她在当地图书馆举办的诗歌比赛中获得了一等奖。', 'contest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arena-1', 'arena', 'The concert will be held at the indoor arena near the river.', '音乐会将在河边的室内竞技场举行。', 'arena');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solo-1', 'solo', 'Her solo was the best part of the whole evening.', '她的独奏是整晚最精彩的部分。', 'solo');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solo-2', 'solo', 'He completed a solo walk across the country to raise money.', '他独自徒步穿越全国,为慈善筹款。', 'solo');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('choir-1', 'choir', 'I sing in the university choir, and we practise on Monday evenings.', '我在大学合唱团唱歌,我们周一晚上排练。', 'choir');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ensemble-1', 'ensemble', 'A small jazz ensemble will play during dinner on the last night.', '最后一晚晚餐时,一支小型爵士乐团会演奏。', 'ensemble');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('anniversary-1', 'anniversary', 'My parents are going to Paris for their wedding anniversary next month.', '我父母下个月要去巴黎过结婚纪念日。', 'anniversary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wedding-1', 'wedding', 'We''ve been invited to a wedding in Scotland at the end of June.', '我们受邀参加六月底在苏格兰举行的一场婚礼。', 'wedding');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aquarium-1', 'aquarium', 'The aquarium has a large tank where you can watch sharks being fed.', '水族馆有一个大水箱,可以看到鲨鱼喂食。', 'aquarium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('applaud-1', 'applaud', 'The crowd began to applaud as soon as the runner came into view.', '跑者一出现,人群就开始鼓掌。', 'applaud');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spotlight-1', 'spotlight', 'The spotlight followed the dancer as she moved across the stage.', '聚光灯跟着舞者在舞台上移动。', 'spotlight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('badge-1', 'badge', 'All visitors must wear a badge while they are in the building.', '所有访客在楼内必须佩戴徽章。', 'badge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('token-1', 'token', 'You''ll need a token to use the washing machines in the basement.', '使用地下室的洗衣机需要一枚代币。', 'token');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ribbon-1', 'ribbon', 'The mayor cut the ribbon to open the new sports hall.', '市长剪彩为新体育馆揭幕。', 'ribbon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('banner-1', 'banner', 'Fans held up a huge banner with the team''s name on it.', '球迷举起一条印有球队名字的巨大横幅。', 'banner');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cricket-1', 'cricket', 'We watched a game of cricket on the village green on Sunday.', '周日我们在村里的草地上看了一场板球赛。', 'cricket');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deck-1', 'deck', 'We sat on the top deck and watched the sun go down.', '我们坐在顶层甲板上看日落。', 'deck');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('raft-1', 'raft', 'The children built a small raft and floated it across the pond.', '孩子们造了一只小木筏,划过了池塘。', 'raft');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('helmet-1', 'helmet', 'You must wear a helmet when you ride a bike on this trail.', '在这条小路上骑车必须戴头盔。', 'helmet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('position-1', 'position', 'We''re looking to fill the position of sales assistant by next month.', '我们希望在下个月前招到销售助理这个职位的人选。', 'position');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('position-2', 'position', 'From this position on the hill, you can see the whole town.', '从山上这个位置,你能看到整个小镇。', 'position');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('applicant-1', 'applicant', 'Each applicant will be asked to give a short talk at the interview.', '每位申请人都要在面试时做一个简短的发言。', 'applicant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('application-form-1', 'application-form', 'Please fill in the application form and return it by Friday.', '请填写申请表,并在周五前交回。', 'application form');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cv-1', 'cv', 'Please send your CV and a covering letter by the end of this week.', '请在本周末前发送你的简历和求职信。', 'CV');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('resume-cv-1', 'resume-cv', 'Keep your résumé to one page when you apply for jobs in America.', '在美国求职时,简历要控制在一页以内。', 'résumé');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cover-letter-1', 'cover-letter', 'A good cover letter explains why you want to work for that company.', '一封好的求职信要说明你为什么想在那家公司工作。', 'cover letter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interview-1', 'interview', 'I''ve got an interview for a job at the hospital on Monday.', '我周一要去医院面试一份工作。', 'interview');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interview-2', 'interview', 'The manager will interview all five candidates over the next two days.', '经理将在接下来两天面试全部五位候选人。', 'interview');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('candidate-1', 'candidate', 'The best candidate for this job will have experience of working with children.', '这份工作的最佳人选应有与儿童打交道的经验。', 'candidate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('qualification-1', 'qualification', 'You don''t need any special qualifications to work in our shop.', '在我们店工作不需要任何特殊的资格。', 'qualifications');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('certificate-1', 'certificate', 'You''ll receive a certificate when you complete the first aid course.', '完成急救课程后,你将获得一份证书。', 'certificate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diploma-1', 'diploma', 'She has a diploma in hotel management from a college in Dublin.', '她持有都柏林一所学院颁发的酒店管理文凭。', 'diploma');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('experience-1', 'experience', 'Do you have any experience of working in a restaurant?', '你有在餐厅工作的经验吗?', 'experience');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('internship-1', 'internship', 'I did a three-month internship at a newspaper during the summer.', '暑假期间我在一家报社实习了三个月。', 'internship');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trainee-1', 'trainee', 'As a trainee, you''ll spend your first month working with an experienced chef.', '作为实习生,你第一个月将跟着一位经验丰富的厨师工作。', 'trainee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('apprentice-1', 'apprentice', 'He started as an apprentice in a garage when he was sixteen.', '他十六岁时在一家修车厂当学徒。', 'apprentice');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('part-time-1', 'part-time', 'I have a part-time job in a café at weekends.', '我周末在一家咖啡馆做兼职。', 'part-time');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('full-time-1', 'full-time', 'The company is offering her a full-time job after she graduates.', '公司打算在她毕业后给她一份全职工作。', 'full-time');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shift-1', 'shift', 'I''m working the early shift tomorrow, so I have to get up at five.', '我明天上早班,所以五点就得起床。', 'shift');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overtime-1', 'overtime', 'Staff are paid extra for any overtime they do at weekends.', '员工周末加班可获得额外报酬。', 'overtime');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flexible-hours-1', 'flexible-hours', 'Flexible hours let me start late on the days I have classes.', '弹性工作时间让我在有课的日子可以晚点上班。', 'Flexible hours');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('salary-1', 'salary', 'The starting salary for this job is about £28,000 a year.', '这份工作的起薪大约是每年 28000 英镑。', 'salary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wage-1', 'wage', 'The hourly wage at the supermarket is higher than at the café.', '超市的时薪比咖啡馆高。', 'wage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bonus-1', 'bonus', 'All staff receive a bonus at the end of a good year.', '业绩好的年份,全体员工年底都会拿到奖金。', 'bonus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pension-1', 'pension', 'The company pays part of your salary into a pension every month.', '公司每月把你工资的一部分存入养老金。', 'pension');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('perk-1', 'perk', 'One of the perks of the job is free lunch in the canteen.', '这份工作的福利之一是在食堂免费吃午饭。', 'perks');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('annual-leave-1', 'annual-leave', 'Staff get twenty-five days of annual leave plus public holidays.', '员工除公共假期外还有二十五天年假。', 'annual leave');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sick-leave-1', 'sick-leave', 'You should call your manager before nine if you need sick leave.', '如果需要请病假,应在九点前打电话给经理。', 'sick leave');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('maternity-leave-1', 'maternity-leave', 'Our company gives six months of maternity leave on full pay.', '我们公司提供六个月全薪产假。', 'maternity leave');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('probation-1', 'probation', 'All new staff are on probation for their first three months.', '所有新员工前三个月都处于试用期。', 'probation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contract-1', 'contract', 'Read your contract carefully before you agree to start work.', '同意开始工作之前,请仔细阅读你的合同。', 'contract');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('employer-1', 'employer', 'My employer pays for me to attend a language course every year.', '我的雇主每年出钱让我上语言课程。', 'employer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('employee-1', 'employee', 'Each employee gets a free parking space behind the office.', '每位雇员都有一个办公室后面的免费停车位。', 'employee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('colleague-1', 'colleague', 'My colleagues organised a small party when I left the company.', '我离开公司时,同事们办了一个小型聚会。', 'colleagues');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('supervisor-1', 'supervisor', 'You should tell your supervisor in advance if you need a day off.', '如果需要请假,你应该提前告诉主管。', 'supervisor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('manager-1', 'manager', 'The restaurant manager will show you around on your first day.', '第一天餐厅经理会带你四处看看。', 'manager');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('personnel-1', 'personnel', 'Please hand your forms in to personnel on the second floor.', '请把表格交到三楼的人事部。', 'personnel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('human-resources-1', 'human-resources', 'Contact human resources if you have any questions about your pay.', '如果对工资有疑问,请联系人力资源部。', 'human resources');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('department-1', 'department', 'She works in the sales department of a large furniture company.', '她在一家大型家具公司的销售部工作。', 'department');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('headquarters-1', 'headquarters', 'The company''s headquarters are in Leeds, but it has offices across Europe.', '公司总部在利兹,但在欧洲各地都设有办事处。', 'headquarters');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('promotion-1', 'promotion', 'He got a promotion after only two years with the company.', '他进公司才两年就升职了。', 'promotion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('promotion-2', 'promotion', 'The shop is running a special promotion on sports shoes this week.', '这家店本周正在做运动鞋的特别促销。', 'promotion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('resign-1', 'resign', 'She decided to resign because the journey to work was too long.', '她决定辞职,因为上班路程太远。', 'resign');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('retire-1', 'retire', 'My father hopes to retire at sixty and move to the coast.', '我父亲希望六十岁退休,然后搬到海边。', 'retire');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('volunteer-1', 'volunteer', 'We need a volunteer to help serve drinks at the charity event.', '我们需要一名志愿者在慈善活动上帮忙倒饮料。', 'volunteer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('volunteer-2', 'volunteer', 'I volunteered to clean the beach with a local group last weekend.', '上周末,我主动和当地一个团体去清理了海滩。', 'volunteered');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recruit-1', 'recruit', 'The museum is hoping to recruit ten volunteers for the summer.', '博物馆希望为暑期招募十名志愿者。', 'recruit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('award-1', 'award', 'She won an award for the best young chef in the region.', '她获得了该地区最佳青年厨师奖。', 'award');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('award-2', 'award', 'The college will award a prize to the student with the highest marks.', '学院将向成绩最高的学生颁发奖品。', 'award');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commission-1', 'commission', 'Our sales staff earn a commission on every car they sell.', '我们的销售人员每卖一辆车都能拿到佣金。', 'commission');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commission-2', 'commission', 'The council has decided to commission a new statue for the square.', '市议会决定委托制作一座新雕像放在广场上。', 'commission');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('benefit-1', 'benefit', 'Free health insurance is one of the main benefits of this job.', '免费医疗保险是这份工作的主要福利之一。', 'benefits');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('benefit-2', 'benefit', 'The whole team will benefit from the new training programme.', '整个团队都将从新的培训计划中受益。', 'benefit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('absenteeism-1', 'absenteeism', 'Poor working conditions can lead to high levels of absenteeism among staff.', '恶劣的工作条件可能导致员工缺勤率居高不下。', 'absenteeism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('secretary-1', 'secretary', 'The school secretary can give you a copy of the timetable.', '学校秘书可以给你一份课程表。', 'secretary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clerk-1', 'clerk', 'I worked as a clerk in a law firm before I went to college.', '上大学前,我在一家律师事务所当职员。', 'clerk');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('night-shift-1', 'night-shift', 'Nurses on the night shift start at eight and finish at seven.', '上夜班的护士八点上班,七点下班。', 'night shift');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unemployment-benefit-1', 'unemployment-benefit', 'You may be able to claim unemployment benefit while you look for work.', '找工作期间,你也许可以申请失业救济金。', 'unemployment benefit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('letter-of-recommendation-1', 'letter-of-recommendation', 'My tutor agreed to write me a letter of recommendation for the job.', '我的导师同意为这份工作给我写一封推荐信。', 'letter of recommendation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('portfolio-1', 'portfolio', 'Art students must hand in a portfolio of their work by Friday.', '艺术专业的学生必须在周五前提交作品集。', 'portfolio');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('portfolio-2', 'portfolio', 'Her investment portfolio includes shares in several large companies.', '她的投资组合包括几家大公司的股票。', 'portfolio');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consultant-1', 'consultant', 'The firm hired a consultant to advise them on saving energy.', '公司聘请了一位顾问,就节能问题提供建议。', 'consultant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assistant-1', 'assistant', 'She started as an assistant in the shop and now runs the business.', '她从店里的助理做起,现在经营着这家店。', 'assistant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('technician-1', 'technician', 'A technician will come to fix the printer this afternoon.', '今天下午技术员会来修打印机。', 'technician');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deputy-1', 'deputy', 'The deputy manager will be in charge while I''m away next week.', '我下周不在时,由副经理负责。', 'deputy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('veteran-1', 'veteran', 'As a veteran of the hotel trade, he knows what guests really want.', '作为酒店业的老手,他知道客人真正想要什么。', 'veteran');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amateur-1', 'amateur', 'Our team is made up of amateur players who train after work.', '我们队由下班后训练的业余球员组成。', 'amateur');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amateur-2', 'amateur', 'Although she''s only an amateur, her paintings are sold in local galleries.', '虽然她只是业余爱好者,但她的画在当地画廊出售。', 'amateur');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('appraisal-1', 'appraisal', 'You''ll have an appraisal with your manager at the end of each year.', '每年年底,你都会和经理进行一次工作考核。', 'appraisal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enrol-1', 'enrol', 'You must enrol on the course by the end of September.', '你必须在九月底前注册这门课程。', 'enrol');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enrolment-1', 'enrolment', 'Enrolment for evening classes begins next Monday in the main building.', '夜校注册下周一在主楼开始。', 'Enrolment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('orientation-1', 'orientation', 'New students will get a campus map during orientation week.', '新生会在迎新周拿到校园地图。', 'orientation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('semester-1', 'semester', 'The second semester begins in February, after a three-week break.', '三周假期过后,第二学期在二月开始。', 'semester');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('term-1', 'term', 'The library stays open until midnight during the summer term.', '夏季学期图书馆开放到午夜。', 'term');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('term-2', 'term', 'Your tutor will explain any technical terms you don''t understand.', '导师会解释你不懂的专业术语。', 'terms');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('course-1', 'course', 'I''m taking a one-year course in business management.', '我正在修一门为期一年的商业管理课程。', 'course');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('module-1', 'module', 'Each module lasts ten weeks and ends with a short written test.', '每个课程模块持续十周,最后有一次简短的笔试。', 'module');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compulsory-1', 'compulsory', 'Statistics is compulsory for all first-year psychology students.', '统计学是心理学专业大一学生的必修课。', 'compulsory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('optional-1', 'optional', 'The field trip is optional, but most students choose to go.', '实地考察是选修的,但大多数学生都会去。', 'optional');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('elective-1', 'elective', 'I chose marine biology as my elective this semester.', '这学期我选了海洋生物学作为选修课。', 'elective');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prerequisite-1', 'prerequisite', 'Basic statistics is a prerequisite for this research methods course.', '基础统计学是这门研究方法课的先修课程。', 'prerequisite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('credit-1', 'credit', 'You need sixty credits to complete the first year of the degree.', '你需要修满六十个学分才能完成学位的第一年。', 'credits');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('credit-2', 'credit', 'Buying a car on credit can cost you more in the long run.', '从长远看,用信用贷款买车可能花费更多。', 'credit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('syllabus-1', 'syllabus', 'You can download the syllabus and reading list from the course website.', '你可以从课程网站下载教学大纲和阅读书目。', 'syllabus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('curriculum-1', 'curriculum', 'The school has added computer programming to its curriculum this year.', '学校今年把计算机编程加入了课程体系。', 'curriculum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lecture-1', 'lecture', 'Today''s lecture will look at the causes of the French Revolution.', '今天的讲座将探讨法国大革命的起因。', 'lecture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lecturer-1', 'lecturer', 'Our lecturer has put all the slides on the university website.', '我们的讲师把所有幻灯片都放到了大学网站上。', 'lecturer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tutorial-1', 'tutorial', 'We''ll discuss your essay plan in next week''s tutorial.', '我们会在下周的辅导课上讨论你的论文提纲。', 'tutorial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tutor-1', 'tutor', 'My tutor suggested that I read more before starting the essay.', '我的导师建议我在动笔前多读些资料。', 'tutor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seminar-1', 'seminar', 'Everyone must read the article before Thursday''s seminar on climate policy.', '大家必须在周四的气候政策研讨会前读完这篇文章。', 'seminar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('workshop-1', 'workshop', 'There''s a free workshop on academic writing in the library this Friday.', '本周五图书馆有一场免费的学术写作工作坊。', 'workshop');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('professor-1', 'professor', 'Professor Lee will give the opening talk at the conference.', '李教授将在会议上作开场发言。', 'Professor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('faculty-1', 'faculty', 'The Faculty of Science is in the new building beside the lake.', '理学院位于湖边的新大楼。', 'Faculty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('campus-1', 'campus', 'Most of the shops and cafés are in the centre of campus.', '大多数商店和咖啡馆都在校园中心。', 'campus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('undergraduate-1', 'undergraduate', 'Undergraduates can borrow up to ten books from the library at a time.', '本科生一次最多可以从图书馆借十本书。', 'Undergraduates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('postgraduate-1', 'postgraduate', 'Postgraduate students have their own study room on the fourth floor.', '研究生在五楼有自己的自习室。', 'Postgraduate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fresher-1', 'fresher', 'As a fresher, I found it difficult to find my way around campus.', '作为新生,我发现在校园里很难找到路。', 'fresher');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alumni-1', 'alumni', 'Many of the college''s alumni come back to give talks to students.', '学院的许多校友回校给学生做讲座。', 'alumni');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mature-student-1', 'mature-student', 'As a mature student, I find it hard to balance work and family.', '作为大龄学生,我觉得很难平衡工作和家庭。', 'mature student');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('international-student-1', 'international-student', 'The support office helps each international student to settle in during the first month.', '支持办公室在第一个月帮助每位留学生适应环境。', 'international student');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bachelors-degree-1', 'bachelors-degree', 'You need a bachelor''s degree to apply for this teaching course.', '申请这门教师课程需要有学士学位。', 'bachelor''s degree');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('masters-degree-1', 'masters-degree', 'She''s doing a master''s degree in engineering at a university in Glasgow.', '她正在格拉斯哥一所大学攻读工程硕士学位。', 'master''s degree');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('doctorate-1', 'doctorate', 'He spent five years working on his doctorate in chemistry.', '他花了五年时间攻读化学博士学位。', 'doctorate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('phd-1', 'phd', 'She''s doing a PhD on the history of medicine in Asia.', '她正在攻读亚洲医学史方向的博士学位。', 'PhD');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('major-1', 'major', 'My major is economics, but I''m also taking a course in history.', '我主修经济学,但也在修一门历史课。', 'major');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('major-2', 'major', 'I decided to major in biology after a great teacher inspired me.', '一位很棒的老师激励了我,于是我决定主修生物学。', 'major');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discipline-1', 'discipline', 'Psychology is a discipline that draws on both science and social studies.', '心理学是一门兼具科学和社会研究的学科。', 'discipline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discipline-2', 'discipline', 'Good teachers can maintain discipline in class without raising their voices.', '好老师不用提高嗓门就能维持课堂纪律。', 'discipline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assignment-1', 'assignment', 'The history assignment has to be at least two thousand words long.', '这份历史作业至少要写两千词。', 'assignment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coursework-1', 'coursework', 'Coursework counts for forty percent of your final mark.', '课程作业占你最终成绩的百分之四十。', 'Coursework');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('essay-1', 'essay', 'I have to write an essay on population growth by next Tuesday.', '我必须在下周二前写一篇关于人口增长的论文。', 'essay');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dissertation-1', 'dissertation', 'I''m writing my dissertation on how tourism affects small islands.', '我正在写学位论文,研究旅游业如何影响小岛。', 'dissertation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thesis-1', 'thesis', 'He finished his thesis on Roman trade and handed it in last week.', '他写完了关于罗马贸易的论文,上周交了上去。', 'thesis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thesis-2', 'thesis', 'The main thesis of the book is that cities shape how we think.', '这本书的主要论点是城市塑造了我们的思维方式。', 'thesis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('draft-1', 'draft', 'Please send me a first draft of your report by Wednesday.', '请在周三前把报告初稿发给我。', 'draft');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('draft-2', 'draft', 'I need to draft an email to the tutor about my late essay.', '我得起草一封邮件给导师,说明论文迟交的事。', 'draft');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deadline-1', 'deadline', 'The deadline for the essay is five o''clock on Friday afternoon.', '论文的截止时间是周五下午五点。', 'deadline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extension-1', 'extension', 'I asked my tutor for an extension because I''d been ill.', '我生病了,所以向导师申请延期。', 'extension');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('submit-1', 'submit', 'You must submit your assignment online before midnight on Sunday.', '你必须在周日午夜前在线提交作业。', 'submit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('presentation-1', 'presentation', 'Each group will give a ten-minute presentation at the end of the course.', '每个小组将在课程结束时做十分钟的展示。', 'presentation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('handout-1', 'handout', 'I''ll give you a handout with all the main points after the lecture.', '讲座结束后,我会发一份包含所有要点的讲义。', 'handout');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('feedback-1', 'feedback', 'Your tutor will give you feedback on your essay within two weeks.', '导师会在两周内就你的论文给出反馈。', 'feedback');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grade-1', 'grade', 'I got a good grade in maths but failed my science test.', '我数学成绩不错,但科学考试没及格。', 'grade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grade-2', 'grade', 'The teachers will grade all the papers by the end of next week.', '老师们将在下周末前批改完所有试卷。', 'grade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mark-1', 'mark', 'You need a mark of at least sixty percent to pass the module.', '这门课程模块至少要得百分之六十的分数才算通过。', 'mark');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mark-2', 'mark', 'It takes the lecturers about two weeks to mark all the exam papers.', '讲师们大约需要两周才能批改完所有试卷。', 'mark');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assessment-1', 'assessment', 'The assessment for this course includes a test and a group project.', '这门课的评估包括一次测验和一个小组项目。', 'assessment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('examination-1', 'examination', 'The final examination will take place in the sports hall in June.', '期末考试将于六月在体育馆举行。', 'examination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('revision-1', 'revision', 'I''ve started my revision, but there''s still a lot to cover.', '我已经开始复习了,但还有很多内容要看。', 'revision');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('revision-2', 'revision', 'The report needs some revision before we send it to the client.', '这份报告在发给客户之前还需要修改。', 'revision');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plagiarism-1', 'plagiarism', 'Plagiarism is taken very seriously, and you could be asked to leave the course.', '抄袭的处理非常严肃,你可能会被要求退出课程。', 'Plagiarism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('attendance-1', 'attendance', 'Attendance at all the seminars is compulsory for first-year students.', '大一学生必须出席所有研讨课。', 'Attendance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('registration-1', 'registration', 'Registration for the conference opens at eight in the main hall.', '会议登记八点在主厅开始。', 'Registration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('student-union-1', 'student-union', 'The student union organises parties and cheap trips throughout the year.', '学生会全年组织派对和便宜的旅行。', 'student union');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('society-1', 'society', 'I''ve joined the film society, and we meet on Tuesday nights.', '我加入了电影社团,我们每周二晚上聚会。', 'society');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('society-2', 'society', 'Technology has changed the way people in modern society communicate.', '科技改变了现代社会人们的交流方式。', 'society');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('counsellor-1', 'counsellor', 'The college counsellor helped me deal with the stress before my exams.', '学院的心理咨询师帮我缓解了考前压力。', 'counsellor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accommodation-office-1', 'accommodation-office', 'Ask at the accommodation office if you need help finding a room.', '如果需要帮忙找房间,可以到住宿办公室咨询。', 'accommodation office');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('careers-service-1', 'careers-service', 'The careers service can check your CV and help you prepare for interviews.', '就业指导中心可以帮你检查简历并准备面试。', 'careers service');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prospectus-1', 'prospectus', 'You can order a free prospectus from the college''s website.', '你可以在学院网站上免费索取招生简章。', 'prospectus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('freshman-1', 'freshman', 'As a freshman, I lived in a dorm right in the middle of campus.', '大一时,我住在校园正中央的宿舍里。', 'freshman');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sophomore-1', 'sophomore', 'She''s a sophomore at a college in Boston, studying computer science.', '她是波士顿一所大学的大二学生,学习计算机科学。', 'sophomore');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('junior-1', 'junior', 'He''s a junior now and has to choose a topic for his final project.', '他现在大三了,必须为毕业设计选题。', 'junior');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('junior-2', 'junior', 'I started as a junior engineer and worked my way up over ten years.', '我从初级工程师做起,用十年时间一步步晋升。', 'junior');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('senior-1', 'senior', 'As a senior, she spends most of her time on her final project.', '作为大四学生,她大部分时间都花在毕业设计上。', 'senior');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('senior-2', 'senior', 'A senior nurse showed me what to do on my first day.', '第一天,一位资深护士教我该做什么。', 'senior');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('headmaster-1', 'headmaster', 'The headmaster gave a short speech at the start of the school year.', '校长在学年开始时作了简短讲话。', 'headmaster');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('principal-1', 'principal', 'The principal of the college will welcome new students on Monday.', '学院院长周一将欢迎新生。', 'principal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('principal-2', 'principal', 'The principal reason for the delay was a shortage of staff.', '延误的主要原因是人手不足。', 'principal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scholar-1', 'scholar', 'The library contains rare books used by scholars from all over the world.', '图书馆收藏着世界各地学者使用的珍本书。', 'scholars');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cram-1', 'cram', 'I had to cram for three days because I''d missed so many classes.', '我缺了很多课,只好突击学习了三天。', 'cram');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('textbook-1', 'textbook', 'The textbook for this course is expensive, so try to buy a used copy.', '这门课的教科书很贵,所以尽量买二手的。', 'textbook');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('humanities-1', 'humanities', 'Students in the humanities often have fewer class hours than those in science.', '人文学科的学生课时通常比理科生少。', 'humanities');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sociology-1', 'sociology', 'In sociology, we study how families and social groups change over time.', '在社会学中,我们研究家庭和社会群体如何随时间变化。', 'sociology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('zoology-1', 'zoology', 'My degree in zoology included a field trip to study wild birds.', '我的动物学学位课程包括一次研究野生鸟类的实地考察。', 'zoology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('biochemistry-1', 'biochemistry', 'Biochemistry is a difficult subject, but there are plenty of jobs for graduates.', '生物化学很难学,但毕业生的工作机会很多。', 'Biochemistry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commerce-1', 'commerce', 'She studied commerce at university and now runs her own small business.', '她在大学学的是商业,现在经营自己的小公司。', 'commerce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('score-1', 'score', 'You need a score of at least 6.5 to get onto this course.', '你至少要考到 6.5 分才能上这门课。', 'score');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('score-2', 'score', 'Students who score above ninety in the test don''t need extra classes.', '测试得分在九十以上的学生不需要额外上课。', 'score');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('refresher-course-1', 'refresher-course', 'I''m taking a refresher course because I haven''t used French for years.', '我已经多年没用法语了,所以在上进修课程。', 'refresher course');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intensive-course-1', 'intensive-course', 'This intensive course covers a full year of Spanish in just eight weeks.', '这门强化课程只用八周就学完一整年的西班牙语内容。', 'intensive course');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('notice-board-1', 'notice-board', 'The exam timetable will be put on the notice board outside the office.', '考试时间表会贴在办公室外的布告栏上。', 'notice board');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('word-limit-1', 'word-limit', 'Your essay will lose marks if it goes over the word limit.', '论文超出字数限制会被扣分。', 'word limit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('take-notes-1', 'take-notes', 'It''s a good idea to take notes during the lecture and read them later.', '听讲座时记笔记,之后再看一遍,是个好办法。', 'take notes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dropout-rate-1', 'dropout-rate', 'The dropout rate is much higher among students who work full-time.', '全职工作的学生辍学率要高得多。', 'dropout rate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('correction-1', 'correction', 'The teacher made several corrections to my essay in red ink.', '老师用红笔在我的论文上做了几处修改。', 'corrections');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('comprehension-1', 'comprehension', 'The reading comprehension test takes about one hour to finish.', '阅读理解测试大约需要一小时完成。', 'comprehension');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('quiz-1', 'quiz', 'We have a short quiz at the start of every Monday class.', '每周一上课开始时我们都有一个小测验。', 'quiz');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('quiz-2', 'quiz', 'The tutor will quiz you on the first three chapters tomorrow.', '导师明天会就前三章对你们进行测验。', 'quiz');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('institute-1', 'institute', 'She''s now working at a research institute in the north of the city.', '她现在在城北的一家研究所工作。', 'institute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('institute-2', 'institute', 'The college has instituted a new system for handing in coursework.', '学院设立了一套新的提交作业制度。', 'instituted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dean-1', 'dean', 'You''ll need a letter from the dean to change your course.', '更换课程需要院长的一封信。', 'dean');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transcript-1', 'transcript', 'The university asked for an official transcript of my school results.', '大学要求我提供一份正式的学校成绩单。', 'transcript');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transcript-2', 'transcript', 'You can read a transcript of the radio programme on our website.', '你可以在我们网站上阅读这期广播节目的文字记录。', 'transcript');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fellowship-1', 'fellowship', 'She was awarded a research fellowship at a university in Canada.', '她获得了加拿大一所大学的研究员职位。', 'fellowship');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('warden-1', 'warden', 'Speak to the warden if you lose the key to your room.', '如果丢了房间钥匙,请联系宿舍管理员。', 'warden');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('library-card-1', 'library-card', 'You''ll need your library card to borrow books or use the computers.', '借书或使用电脑都需要借书卡。', 'library card');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('renew-1', 'renew', 'You can renew your books online if nobody else has asked for them.', '如果没有其他人预约,你可以在线续借图书。', 'renew');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overdue-1', 'overdue', 'You''ll have to pay a small charge for any overdue books.', '过期未还的书要交一小笔费用。', 'overdue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fine-1', 'fine', 'There''s a fine of ten pence a day for books you return late.', '逾期还书每天罚款十便士。', 'fine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fine-2', 'fine', 'The council will fine anyone who leaves rubbish in the street.', '市议会将对在街上乱扔垃圾的人处以罚款。', 'fine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('loan-period-1', 'loan-period', 'The loan period for this book is two weeks, or one if it''s in demand.', '这本书的借期是两周,如果需求量大则是一周。', 'loan period');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reserve-1', 'reserve', 'You can reserve the book online and collect it at the front desk.', '你可以在网上预约这本书,然后到前台领取。', 'reserve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reserve-2', 'reserve', 'We saw several rare birds at the nature reserve near the coast.', '我们在海岸附近的自然保护区看到了几种珍稀鸟类。', 'reserve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('catalogue-1', 'catalogue', 'Search the library catalogue to find out where the book is kept.', '查一下图书馆目录,看看这本书放在哪里。', 'catalogue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reference-book-1', 'reference-book', 'You can''t take this reference book out of the library.', '这本参考书不能带出图书馆。', 'reference book');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('periodical-1', 'periodical', 'Recent periodicals are on the shelves near the main entrance.', '最近几期的期刊放在正门附近的书架上。', 'periodicals');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('journal-1', 'journal', 'You''ll find that article in a psychology journal in the library.', '你可以在图书馆的一本心理学期刊上找到那篇文章。', 'journal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('journal-2', 'journal', 'I keep a journal of everything I read for my research.', '我把为研究读过的所有内容都记在日志里。', 'journal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('magazine-1', 'magazine', 'I read an interesting article about sleep in a science magazine.', '我在一本科学杂志上读到一篇关于睡眠的有趣文章。', 'magazine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('database-1', 'database', 'The library''s online database gives you access to thousands of articles.', '图书馆的在线数据库能让你查阅数千篇文章。', 'database');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('archive-1', 'archive', 'The town''s archive holds old photos and letters from the last century.', '小镇的档案馆收藏着上个世纪的老照片和信件。', 'archive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('manuscript-1', 'manuscript', 'The museum has an original manuscript of one of his early novels.', '博物馆藏有他早期一部小说的手稿原件。', 'manuscript');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('edition-1', 'edition', 'Make sure you buy the latest edition of the textbook.', '一定要买这本教科书的最新版本。', 'edition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('volume-1', 'volume', 'The second volume of the encyclopedia is missing from the shelf.', '书架上缺了这部百科全书的第二卷。', 'volume');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('volume-2', 'volume', 'Please turn down the volume on your computer in the study room.', '在自习室请把电脑音量调低。', 'volume');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('author-1', 'author', 'The author of this book will give a talk at the library tomorrow.', '这本书的作者明天将在图书馆做讲座。', 'author');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('publisher-1', 'publisher', 'The publisher has agreed to print a cheaper version for students.', '出版商同意为学生印刷更便宜的版本。', 'publisher');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bibliography-1', 'bibliography', 'Remember to list every book you''ve used in the bibliography.', '记得在参考书目中列出你用过的每一本书。', 'bibliography');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('photocopy-1', 'photocopy', 'You can get a photocopy of the article from the desk upstairs.', '你可以到楼上的服务台复印这篇文章。', 'photocopy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('photocopy-2', 'photocopy', 'Please photocopy this chapter and give it to the rest of the group.', '请复印这一章,发给小组其他成员。', 'photocopy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('printer-1', 'printer', 'The printer on the second floor has run out of paper again.', '三楼的打印机又没纸了。', 'printer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scanner-1', 'scanner', 'You can use the scanner in the library to copy old documents.', '你可以用图书馆的扫描仪复制旧文件。', 'scanner');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('study-room-1', 'study-room', 'You can book a study room for up to three hours a day.', '自习室每天最多可预订三小时。', 'study room');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('self-service-1', 'self-service', 'There''s a self-service machine where you can return books at any time.', '有一台自助机,你可以随时还书。', 'self-service');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('librarian-1', 'librarian', 'Ask the librarian if you can''t find what you''re looking for.', '如果找不到需要的资料,可以问图书管理员。', 'librarian');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('atlas-1', 'atlas', 'You''ll find an atlas of the world on the shelf by the window.', '窗边的书架上有一本世界地图集。', 'atlas');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('encyclopedia-1', 'encyclopedia', 'An online encyclopedia is a useful place to start your research.', '网络百科全书是开始研究的好起点。', 'encyclopedia');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('almanac-1', 'almanac', 'The farmers'' almanac lists the best dates for planting each year.', '农民年鉴列出了每年最佳的种植日期。', 'almanac');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('leaflet-1', 'leaflet', 'Take a leaflet from the desk for details of the summer courses.', '从服务台取一张传单,了解暑期课程的详情。', 'leaflet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('memoir-1', 'memoir', 'Her memoir describes her childhood in a small fishing village.', '她的回忆录描述了她在一个小渔村的童年。', 'memoir');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('monograph-1', 'monograph', 'He spent years writing a monograph on the birds of South America.', '他花了多年时间撰写一部关于南美鸟类的专著。', 'monograph');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chapter-1', 'chapter', 'For Monday, please read the first chapter of the book.', '周一之前,请读完这本书的第一章。', 'chapter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('index-1', 'index', 'Look in the index at the back to find the page you need.', '查看书后的索引,找到你需要的页码。', 'index');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('glossary-1', 'glossary', 'You''ll find a glossary of technical words at the end of the book.', '书的末尾有一份专业词汇的术语表。', 'glossary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heading-1', 'heading', 'Use clear headings to divide your report into separate sections.', '用清晰的标题把报告分成不同的部分。', 'headings');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subheading-1', 'subheading', 'Each section of the report should have its own subheading.', '报告的每个部分都应有自己的副标题。', 'subheading');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('keyword-1', 'keyword', 'Type a keyword into the search box to find articles on your topic.', '在搜索框中输入关键词,查找与你的主题相关的文章。', 'keyword');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('excerpt-1', 'excerpt', 'We''ll read an excerpt from the novel and then discuss it in groups.', '我们先读这部小说的一段摘录,然后分组讨论。', 'excerpt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('synopsis-1', 'synopsis', 'Write a short synopsis of the book in about two hundred words.', '用大约两百词写一份这本书的简短梗概。', 'synopsis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abridge-1', 'abridge', 'The publisher decided to abridge the novel to make it easier for schools.', '出版商决定删节这部小说,让它更适合学校使用。', 'abridge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('photocopier-1', 'photocopier', 'The photocopier near the entrance only takes coins, not cards.', '入口附近的复印机只收硬币,不能刷卡。', 'photocopier');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('skim-1', 'skim', 'Try to skim the chapter first, then go back and take notes.', '先试着略读这一章,然后再回头做笔记。', 'skim');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scan-1', 'scan', 'Scan the list quickly to see if your name is on it.', '快速扫一眼名单,看看上面有没有你的名字。', 'Scan');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scan-2', 'scan', 'You can scan the document and send it to me by email.', '你可以把文件扫描后通过邮件发给我。', 'scan');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('browse-1', 'browse', 'I like to browse the shelves in the library when I have time.', '有时间时,我喜欢在图书馆的书架间浏览。', 'browse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bookworm-1', 'bookworm', 'My flatmate is a real bookworm and reads at least two novels a week.', '我的室友是个十足的书虫,每周至少读两本小说。', 'bookworm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('non-fiction-1', 'non-fiction', 'Most of the non-fiction section is on the third floor of the library.', '非虚构类图书大多在图书馆四楼。', 'non-fiction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('back-issue-1', 'back-issue', 'You can find back issues of the journal in the basement.', '你可以在地下室找到这本期刊的过刊。', 'back issues');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stack-1', 'stack', 'There''s a stack of old exam papers on the table by the door.', '门边的桌子上有一堆旧试卷。', 'stack');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stack-2', 'stack', 'Older books are kept in the stacks and must be requested at the desk.', '较旧的书放在书库里,要到服务台申请调阅。', 'stacks');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('footnote-1', 'footnote', 'Please give the source of each quotation in a footnote.', '请在脚注中注明每处引文的出处。', 'footnote');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('booklet-1', 'booklet', 'The booklet you''ve been given explains how to use the library.', '发给你们的小册子说明了如何使用图书馆。', 'booklet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('handbook-1', 'handbook', 'All the rules about late essays are in the student handbook.', '所有关于迟交论文的规定都在学生手册里。', 'handbook');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('directory-1', 'directory', 'You can find the tutor''s phone number in the staff directory.', '你可以在员工名录里找到导师的电话号码。', 'directory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bulletin-1', 'bulletin', 'The department sends out a weekly bulletin with news about upcoming events.', '院系每周发一份简报,介绍即将举行的活动。', 'bulletin');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('folder-1', 'folder', 'Save all your project files in one folder on the shared drive.', '把所有项目文件保存在共享盘的一个文件夹里。', 'folder');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('research-1', 'research', 'Her research looks at how children learn a second language.', '她的研究关注儿童如何学习第二语言。', 'research');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('research-2', 'research', 'I need to research the topic properly before I start writing.', '动笔之前,我需要好好研究这个课题。', 'research');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('project-1', 'project', 'Our group project is about recycling in the local community.', '我们的小组项目是关于当地社区的垃圾回收。', 'project');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('proposal-1', 'proposal', 'You must hand in your research proposal to your tutor by March.', '你必须在三月前把研究开题报告交给导师。', 'proposal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('objective-1', 'objective', 'The main objective of the study is to measure noise levels near schools.', '这项研究的主要目标是测量学校附近的噪音水平。', 'objective');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('objective-2', 'objective', 'It''s hard to stay objective when you''re writing about your own family.', '写自己的家人时,很难保持客观。', 'objective');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('methodology-1', 'methodology', 'In this section, you should explain the methodology of your study.', '在这一部分,你应该说明你研究的方法论。', 'methodology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('questionnaire-1', 'questionnaire', 'We gave out a questionnaire to two hundred students in the canteen.', '我们在食堂向两百名学生发放了问卷。', 'questionnaire');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('survey-1', 'survey', 'The survey found that most students walk or cycle to college.', '调查发现,大多数学生步行或骑车上学。', 'survey');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('survey-2', 'survey', 'We plan to survey local shoppers about their use of plastic bags.', '我们计划调查当地购物者使用塑料袋的情况。', 'survey');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interviewee-1', 'interviewee', 'Each interviewee was asked the same ten questions about their diet.', '每位受访者都被问了同样十个关于饮食的问题。', 'interviewee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('respondent-1', 'respondent', 'More than half the respondents said they used public transport every day.', '超过一半的调查对象表示他们每天乘坐公共交通。', 'respondents');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sample-1', 'sample', 'We used a sample of one hundred people from different age groups.', '我们使用了一个来自不同年龄段的一百人样本。', 'sample');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('data-1', 'data', 'We''ll collect the data first and then look for any patterns.', '我们先收集数据,再寻找其中的规律。', 'data');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('statistics-1', 'statistics', 'Official statistics show that fewer people are buying newspapers.', '官方统计数据显示,买报纸的人越来越少。', 'statistics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('statistics-2', 'statistics', 'Statistics is the hardest part of my psychology course this year.', '统计学是我今年心理学课程中最难的部分。', 'Statistics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('analysis-1', 'analysis', 'Our analysis of the results will take at least another two weeks.', '我们对结果的分析至少还需要两周。', 'analysis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('findings-1', 'findings', 'The findings of the study will be published in a journal next year.', '这项研究的发现将于明年发表在期刊上。', 'findings');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conclusion-1', 'conclusion', 'You should restate your main idea in the conclusion of your essay.', '你应该在论文结论中重申你的主要观点。', 'conclusion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('appendix-1', 'appendix', 'Put a copy of your questionnaire in the appendix at the end.', '把问卷放在文末的附录中。', 'appendix');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('literature-review-1', 'literature-review', 'I''ve almost finished the literature review, but I still need to read two articles.', '我的文献综述快写完了,但还要读两篇文章。', 'literature review');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('case-study-1', 'case-study', 'We looked at one small company as a case study for the course.', '我们把一家小公司作为这门课的个案研究对象。', 'case study');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('field-trip-1', 'field-trip', 'We''re going on a field trip to the coast to study rock pools.', '我们要去海边实地考察,研究岩石潮池。', 'field trip');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('experiment-1', 'experiment', 'We need to repeat the experiment because the first results were unclear.', '我们需要重做实验,因为第一次的结果不明确。', 'experiment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('observation-1', 'observation', 'Our conclusions are based on careful observation of the children at play.', '我们的结论基于对孩子们玩耍时的仔细观察。', 'observation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trial-1', 'trial', 'The trial of the new teaching method will run for six months.', '新教学方法的试验将持续六个月。', 'trial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trial-2', 'trial', 'The trial lasted two weeks, and the man was found not guilty.', '审判持续了两周,该男子被判无罪。', 'trial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outline-1', 'outline', 'Please show me an outline of your essay before you start writing.', '开始写之前,请给我看一下你的论文大纲。', 'outline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('summary-1', 'summary', 'Write a brief summary of the article in your own words.', '用你自己的话写一篇这篇文章的简短摘要。', 'summary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abstract-1', 'abstract', 'Read the abstract first to see if the article is useful to you.', '先读摘要,看看这篇文章对你是否有用。', 'abstract');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abstract-2', 'abstract', 'Young children often find it hard to understand abstract ideas like time.', '幼儿往往很难理解时间这样的抽象概念。', 'abstract');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chart-1', 'chart', 'The chart on page ten shows how spending has changed since 2000.', '第十页的图表显示了 2000 年以来支出的变化。', 'chart');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diagram-1', 'diagram', 'Label each part of the machine on the diagram in your notes.', '在笔记的示意图上标出机器的各个部分。', 'diagram');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('graph-1', 'graph', 'The graph shows that sales rise sharply just before the holidays.', '曲线图显示,销量在假期前急剧上升。', 'graph');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('table-1', 'table', 'The table below compares the cost of living in three cities.', '下表比较了三个城市的生活成本。', 'table');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('visual-aid-1', 'visual-aid', 'Using a visual aid can make your talk much easier to follow.', '使用视觉辅助工具能让你的发言更容易理解。', 'visual aid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('teamwork-1', 'teamwork', 'Good teamwork is essential if you want to finish the project on time.', '想按时完成项目,良好的团队合作必不可少。', 'teamwork');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('division-of-labour-1', 'division-of-labour', 'A clear division of labour meant that each of us knew what to do.', '明确的分工让我们每个人都清楚自己该做什么。', 'division of labour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('concise-1', 'concise', 'Keep your answers clear and concise, as you only have ten minutes.', '回答要清楚简洁,因为你只有十分钟。', 'concise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wordy-1', 'wordy', 'Your essay is rather wordy, so try to cut out some sentences.', '你的论文有些啰嗦,试着删掉一些句子。', 'wordy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('redundant-1', 'redundant', 'This word is redundant here, because you''ve already said the same thing.', '这个词在这里是多余的,因为你已经说过同样的意思了。', 'redundant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('redundant-2', 'redundant', 'Forty workers were made redundant when the factory closed last year.', '去年工厂关闭时,四十名工人被裁员。', 'redundant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clarity-1', 'clarity', 'Your tutor will give you marks for clarity as well as for your ideas.', '导师既看你的观点,也会就表达是否清晰给分。', 'clarity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brief-1', 'brief', 'I''d like to make a few brief comments before we start the discussion.', '开始讨论之前,我想简短说几句。', 'brief');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brief-2', 'brief', 'Our manager gave us a brief on the new project this morning.', '今天上午经理就新项目给我们做了简报。', 'brief');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('paraphrase-1', 'paraphrase', 'Try to paraphrase the author''s ideas instead of copying the exact words.', '尽量改述作者的观点,不要照抄原文。', 'paraphrase');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interrupt-1', 'interrupt', 'Sorry to interrupt, but could you repeat the last point, please?', '抱歉打断一下,您能再说一遍最后一点吗?', 'interrupt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('skip-1', 'skip', 'You can skip the second chapter, as it won''t be in the exam.', '第二章你可以跳过,因为考试不考。', 'skip');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overview-1', 'overview', 'The first lecture will give you an overview of the whole course.', '第一次讲座将为你概述整门课程。', 'overview');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rewrite-1', 'rewrite', 'I had to rewrite the introduction because my tutor found it unclear.', '导师觉得引言不清楚,所以我只好重写。', 'rewrite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('panel-1', 'panel', 'A panel of three experts will judge the students'' projects.', '由三位专家组成的专家组将评审学生的项目。', 'panel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('format-1', 'format', 'Your report must follow the format given in the course handbook.', '你的报告必须遵循课程手册中规定的格式。', 'format');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enquiry-1', 'enquiry', 'Please direct any enquiry about fees to the main office.', '有关费用的任何询问,请直接联系总办公室。', 'enquiry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enquire-1', 'enquire', 'I''m calling to enquire about the French classes you offer.', '我打电话是想询问你们开设的法语课。', 'enquire');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('display-1', 'display', 'Students'' paintings are on display in the hall this week.', '本周学生们的画作在大厅展出。', 'display');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('display-2', 'display', 'The screen will display your exam results when you enter your number.', '输入学号后,屏幕会显示你的考试成绩。', 'display');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recommendation-1', 'recommendation', 'The report ends with a recommendation to build more cycle paths.', '报告最后建议修建更多自行车道。', 'recommendation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('announcement-1', 'announcement', 'There will be an announcement about the exam dates next week.', '下周会发布关于考试日期的公告。', 'announcement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('profile-1', 'profile', 'Update your online profile so that employers can see your experience.', '更新你的网上简介,让雇主能看到你的经历。', 'profile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('batch-1', 'batch', 'We''ll send out the next batch of letters to students on Friday.', '我们将在周五给学生寄出下一批信件。', 'batch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('postpone-1', 'postpone', 'We''ve had to postpone the meeting until next Thursday.', '我们不得不把会议推迟到下周四。', 'postpone');
